//! Drives the `kpf` binary offline through the life of a committee market (docs/DESIGN-COMMITTEE.md): a committee, three
//! members, an epoch's epoch tables, a market, signed signed prices, two orders, the open, a close and a liquidation at attested
//! prices, a cure, the lease, every hand-over and price-free exit, and the committee's exits. Funding files list synthetic
//! UTXOs (the builders and the local verification need no chain); the DAA a node would report is written into each
//! object file. Keys are generated by `kpf keygen` into a temporary directory. No node is contacted and nothing is
//! submitted.

use std::path::PathBuf;
use std::process::Command;

use serde_json::{json, Value};

struct H {
    dir: PathBuf,
    n: usize,
    last: String,
}

impl Drop for H {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn bin() -> Command {
    Command::new(env!("CARGO_BIN_EXE_kpf"))
}

impl H {
    fn new(tag: &str) -> H {
        let dir = std::env::temp_dir().join(format!("kpf-committee-cli-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        H { dir, n: 0, last: String::new() }
    }
    fn p(&self, name: &str) -> String {
        self.dir.join(name).display().to_string()
    }
    fn run(&self, args: &[&str]) -> (bool, String, String) {
        let o = bin().args(args).output().expect("run kpf");
        (o.status.success(), String::from_utf8_lossy(&o.stdout).into_owned(), String::from_utf8_lossy(&o.stderr).into_owned())
    }
    fn ok(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(ok, "kpf {args:?} failed:
{err}
{out}");
        // `KPF_COST_LOG=FILE`: the size and the masses of every transaction the tests build, by command.
        if let Ok(f) = std::env::var("KPF_COST_LOG") {
            if let Some(l) = out.lines().find(|l| l.contains("compute mass")) {
                use std::io::Write as _;
                let mut w = std::fs::OpenOptions::new().create(true).append(true).open(f).unwrap();
                writeln!(w, "{}	{}", args[0], l).unwrap();
            }
        }
        out
    }
    fn fail(&self, args: &[&str]) -> String {
        let (ok, out, err) = self.run(args);
        assert!(!ok, "kpf {args:?} should have failed:\n{out}");
        err
    }
    fn key(&self, name: &str) -> String {
        let path = self.p(&format!("{name}.key.json"));
        self.ok(&["keygen", "--out", &path]);
        path
    }
    /// A funding file of one synthetic UTXO of `kas` KAS.
    fn funding(&mut self, kas: u64) -> String {
        self.n += 1;
        let txid = format!("{:064x}", 0x5eed_0000u64 + self.n as u64);
        let path = self.p(&format!("funding-{}.json", self.n));
        std::fs::write(&path, serde_json::to_string(&json!([{ "txid": txid, "index": 0, "amount": kas * 100_000_000, "daa": 0 }])).unwrap()).unwrap();
        path
    }
    /// Runs a builder (funded by `funder` with a fresh funding file) into a fresh out-dir; returns the out-dir of its
    /// dry run.
    fn build(&mut self, funder: &str, args: &[&str]) -> String {
        let fund = self.funding(100_000);
        self.n += 1;
        let out = self.p(&format!("out{}", self.n));
        let mut a: Vec<&str> = args.to_vec();
        a.extend(["--funder", funder, "--funding", &fund, "--out-dir", &out]);
        let stdout = self.ok(&a);
        assert!(stdout.contains("not submitted"), "{stdout}");
        self.last = stdout;
        format!("{out}/dry-run")
    }
    /// The object file of `dir` whose name ends with `kind`, its DAA set to `daa`.
    fn obj(&self, dir: &str, kind: &str, daa: u64) -> String {
        let want = format!("-{}.json", kind.replace(' ', "-"));
        let mut all: Vec<PathBuf> = std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).filter(|p| p.to_string_lossy().ends_with(&want)).collect();
        all.sort();
        let f = all.first().unwrap_or_else(|| panic!("no {kind} in {dir}")).clone();
        let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&f).unwrap()).unwrap();
        v["daa"] = json!(daa);
        std::fs::write(&f, serde_json::to_string_pretty(&v).unwrap()).unwrap();
        f.display().to_string()
    }
    /// The out-dir of the last dry run `build` made.
    fn last_dir(&self) -> String {
        format!("{}/dry-run", self.p(&format!("out{}", self.n)))
    }
    fn step(&mut self, funder: &str, args: &[&str], kind: &str, daa: u64) -> String {
        let d = self.build(funder, args);
        self.obj(&d, kind, daa)
    }
}

const FEED: &str = "kpf feed definition v1\nquantity: example underlying\nunit: KAS per whole unit\nsources: median of three named public sources\ntime: the price at the DAA score t0, mapped to the accepting block's timestamp\nsessions: always open\ndisagreement: a signed price is true if within 0.5 % of the median\n";

/// A committee with three members (30, 22 and 15 KAS: 67 KAS, each needed for a quorum of 67 %), rolled into the epoch
/// [33,000, 36,000), and a market priced by it. Returns (funder, member keys, committee object, epoch table, market file).
fn setup(h: &mut H) -> (String, Vec<String>, String, String, String) {
    let funder = h.key("funder");
    let members: Vec<String> = (0..3).map(|i| h.key(&format!("member{i}"))).collect();
    let committee_file = h.p("committee.json");
    let d = h.build(&funder, &["committee-create", "--daa", "30000", "--out", &committee_file]);
    let mut committee = h.obj(&d, "committee", 30_000);
    assert!(h.last.contains("committee id"), "{}", h.last);
    let out = h.ok(&["committee-check", "--committee", &committee_file, "--object", &committee]);
    assert!(out.contains("OK: the id is that of one empty committee"), "{out}");
    for (i, kas) in [(0, "30"), (1, "22"), (2, "15")] {
        committee = h.step(&funder, &["committee-join", "--committee", &committee, "--genesis", &committee_file, "--member", &i.to_string(), "--amount", kas, "--owner", &members[i]], "committee", 30_100 + i as u64);
    }
    // Review C2: who puts KAS into a committee shows that it began empty, or says that it did not check.
    let fund0 = h.funding(1_000);
    assert!(h.fail(&["committee-join", "--committee", &committee, "--member", "3", "--amount", "10", "--funder", &funder, "--funding", &fund0]).contains("give --genesis"));
    let other = h.p("other-committee.json");
    h.build(&funder, &["committee-create", "--daa", "30000", "--epoch-daa", "6000", "--out", &other]);
    assert!(h.fail(&["committee-join", "--committee", &committee, "--genesis", &other, "--member", "3", "--amount", "10", "--funder", &funder, "--funding", &fund0]).contains("not the committee of these genesis facts"));
    // Below minMemberStake, and a taken member while others are empty.
    let fund = h.funding(1_000);
    assert!(h.fail(&["committee-join", "--committee", &committee, "--genesis", &committee_file, "--member", "3", "--amount", "9", "--funder", &funder, "--funding", &fund]).contains("at least 10 KAS"));
    assert!(h.fail(&["committee-join", "--committee", &committee, "--genesis", &committee_file, "--member", "0", "--amount", "100", "--funder", &funder, "--funding", &fund]).contains("cannot be taken now"));
    // Before the epoch ends there is nothing to roll.
    assert!(h.fail(&["committee-roll", "--committee", &committee, "--daa", "32999", "--funder", &funder, "--funding", &fund]).contains("has not ended"));
    let d = h.build(&funder, &["committee-roll", "--committee", &committee, "--daa", "33000"]);
    assert!(h.last.contains("epoch [33000, 36000) with 4 epoch tables"), "{}", h.last);
    let epoch_table = h.obj(&d, "epoch table", 33_000);
    let committee = h.obj(&d, "committee", 33_000);
    let show = h.ok(&["committee-show", "--committee", &committee, "--daa", "33100"]);
    assert!(show.contains("total stake 67 KAS") && show.contains("member  0  30 KAS"), "{show}");
    let feed = h.p("feed.txt");
    std::fs::write(&feed, FEED).unwrap();
    let market = h.p("market.json");
    let out = h.ok(&["c-market", "--committee", &committee_file, "--feed", &feed, "--out", &market]);
    assert!(out.contains("market id") && out.contains("no party states a price"), "{out}");
    let out = h.ok(&["c-check", "--market", &market, "--feed", &feed]);
    assert!(out.contains("OK: the feed definition is the market's") && out.contains("OK: the committee id is that of one empty committee"), "{out}");
    assert!(!out.contains("WARNING"), "{out}");
    // Review C2 (C2-F1): a market whose g leaves the committee's spread no margin is refused (the committee's spread is
    // 0.1 %, so g must be at least 0.4 %).
    assert!(h.fail(&["c-market", "--committee", &committee_file, "--feed", &feed, "--g-bps", "39", "--out", &h.p("tight.json")]).contains("g must be at least 4 times the spread"));
    let out = h.ok(&["c-market", "--committee", &committee_file, "--feed", &feed, "--g-bps", "40", "--mmr-bps", "30", "--out", &h.p("edge.json")]);
    assert!(out.contains("WARNING: the maintenance margin"), "{out}");
    (funder, members, committee, epoch_table, market)
}

/// The three members sign `price` for the time `t0`; returns the `--signed-price FILE` arguments.
fn signed_prices(h: &H, market: &str, members: &[String], t0: u64, price: &str) -> Vec<String> {
    let mut v = vec![];
    for (i, k) in members.iter().enumerate() {
        let f = h.p(&format!("price-{t0}-{i}.json"));
        h.ok(&["price-sign", "--market", market, "--t0", &t0.to_string(), "--price", price, "--key", k, "--out", &f]);
        v.push("--signed-price".to_string());
        v.push(f);
    }
    v
}

fn with<'a>(base: &[&'a str], extra: &'a [String]) -> Vec<&'a str> {
    let mut v = base.to_vec();
    v.extend(extra.iter().map(String::as_str));
    v
}

/// Two orders of 10 units at 10 KAS (the long's rate 1, the short's 2), opened at DAA 33,400.
fn open_pair(h: &mut H, funder: &str, market: &str, long: &str, short: &str) -> String {
    let lo = h.step(funder, &["c-order", "--market", market, "--side", "long", "--size", "10", "--limit", "10", "--rate", "1", "--expiry", "9000000", "--owner", long], "committee order", 33_100);
    let so = h.step(funder, &["c-order", "--market", market, "--side", "short", "--size", "10", "--limit", "10", "--rate", "2", "--expiry", "9000000", "--owner", short], "committee order", 33_100);
    let p = h.step(funder, &["c-open", "--long", &lo, "--short", &so, "--n", "10", "--x", "10", "--daa", "33400"], "committee pair", 33_400);
    assert!(h.last.contains("pair [9 .. 12] KAS of 10 units at 10 KAS") && h.last.contains("lease until DAA 6081400"), "{}", h.last);
    p
}

#[test]
fn a_committee_market_from_the_command_line() {
    let mut h = H::new("life");
    let (funder, members, _committee, epoch_table, market) = setup(&mut h);
    let (long, short) = (h.key("long"), h.key("short"));
    let pair = open_pair(&mut h, &funder, &market, &long, &short);

    // Entering with the market file one checked: the same market passes, another is refused.
    let fund1 = h.funding(1_000);
    assert!(h.fail(&["c-assign", "--pair", &pair, "--side", "long", "--x", "10", "--market", &h.p("edge.json"), "--key", &long, "--funder", &funder, "--funding", &fund1]).contains("not of the market file"));
    // A member signs one price a signed price, no signed price of the future, and any price up to the epoch table's limit.
    let dup = h.p("dup.json");
    h.ok(&["price-sign", "--market", &market, "--t0", "33499", "--price", "10", "--key", &members[0], "--out", &dup]);
    assert!(h.fail(&["price-sign", "--market", &market, "--t0", "33499", "--price", "11", "--key", &members[0], "--out", &dup]).contains("a second price for one time"));
    assert!(h.fail(&["price-sign", "--market", &market, "--t0", "33500", "--daa", "33499", "--price", "10", "--key", &members[0], "--out", &h.p("future.json")]).contains("after the present"));
    let out = h.ok(&["price-sign", "--market", &market, "--t0", "33499", "--price", "2000000", "--key", &members[1], "--out", &h.p("high.json")]);
    assert!(out.contains("above this market's priceMax"), "{out}");
    // What the signed prices attest, without building anything.
    let t1 = signed_prices(&h, &market, &members, 33_500, "10.5");
    let out = h.ok(&with(&["price-check", "--market", &market, "--epoch-table", &epoch_table], &t1));
    assert!(out.contains("attested: 10.5 KAS at DAA 33500: 3 members signed within 0.1 % of it"), "{out}");
    // One member is 30 of 67 KAS, below the 44.89 a price needs: no price.
    let fund = h.funding(1_000);
    let err = h.fail(&with(&["c-close", "--pair", &pair, "--side", "long", "--epoch-table", &epoch_table, "--key", &long, "--funder", &funder, "--funding", &fund], &t1[..2]));
    assert!(err.contains("no price") && err.contains("below the quorum"), "{err}");

    // The long closes at the attested 10.5: paid at 10.5 less g (0.5 %).
    let w = h.step(&funder, &with(&["c-close", "--pair", &pair, "--side", "long", "--epoch-table", &epoch_table, "--key", &long], &t1), "committee pending part", 33_510);
    assert!(h.last.contains("paid at 10.4475 KAS"), "{}", h.last);
    h.build(&funder, &["c-finalize", "--pending", &w]);
    assert!(h.last.contains("valid (landed 10 DAA after its time): the long 14.475 KAS, the short 15.725 KAS"), "{}", h.last);
    // The same claim landed 101 DAA after its time is void.
    let late = h.obj(std::path::Path::new(&w).parent().unwrap().to_str().unwrap(), "committee pending part", 33_601);
    h.build(&funder, &["c-finalize", "--pending", &late]);
    assert!(h.last.contains("VOID") && h.last.contains("restored part"), "{}", h.last);

    // A liquidation of the long at 9.28 for another signed price; 9.3 does not liquidate.
    let t2 = signed_prices(&h, &market, &members, 33_600, "9.28");
    let t3 = signed_prices(&h, &market, &members, 33_700, "9.5");
    let err = h.fail(&with(&["c-liquidate", "--pair", &pair, "--side", "long", "--epoch-table", &epoch_table, "--funder", &funder, "--funding", &fund], &t3));
    assert!(err.contains("does not liquidate the long"), "{err}");
    let w = h.step(&funder, &with(&["c-liquidate", "--pair", &pair, "--side", "long", "--epoch-table", &epoch_table], &t2), "committee pending part", 33_610);
    assert!(h.last.contains("liquidation: the fee"), "{}", h.last);
    h.build(&funder, &["c-finalize", "--pending", &w]);
    assert!(h.last.contains("the winner keeps the part") && h.last.contains("forfeited part"), "{}", h.last);
    h.build(&long, &["c-cure", "--pending", &w]);
    assert!(h.last.contains("cured: the bound moves to"), "{}", h.last);
    let out = h.ok(&["inspect", &w]);
    assert!(out.contains("a liquidation of the long at 9.28 KAS") && out.contains("VALID"), "{out}");

    // The state of the pair for the long, with the feed at 9.2: liquidatable, an action is due (exit code 3).
    let (ok, out, err) = h.run(&["c-watch", "--me", &long, "--object", &pair, "--daa", "33700", "--price", "9.2"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("the LONG can be LIQUIDATED"), "{out}\n{err}");
    let out = h.ok(&["c-watch", "--me", &long, "--object", &pair, "--daa", "33700", "--price", "10"]);
    assert!(out.contains("neither side can be liquidated") && out.contains("lease ends in"), "{out}");
    // The last quarter of the lease, and the loser of a pending liquidation: both are told to act.
    let (ok, out, err) = h.run(&["c-watch", "--me", &long, "--object", &pair, "--daa", "5000000", "--price", "10"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("the lease is in its last quarter"), "{out}\n{err}");
    let (ok, out, err) = h.run(&["c-watch", "--me", &long, "--object", &w, "--daa", "33620"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("your side is being liquidated"), "{out}\n{err}");
    let out = h.ok(&["c-quote", "--pair", &pair, "--prices", "9,10,12"]);
    assert!(out.contains("long liquidatable"), "{out}");
}

#[test]
fn the_lease_the_hand_overs_and_the_exits_from_the_command_line() {
    let mut h = H::new("paths");
    let (funder, members, committee, epoch_table, market) = setup(&mut h);
    let (long, short) = (h.key("long"), h.key("short"));
    let pair = open_pair(&mut h, &funder, &market, &long, &short);

    // The lease (6,081,400) moves only with a signed price from DAA 1,545,400 on; the epoch that holds it is 505 epochs on.
    let fund = h.funding(1_000);
    let early = signed_prices(&h, &market, &members, 33_500, "10");
    let err = h.fail(&with(&["c-keep-alive", "--pair", &pair, "--epoch-table", &epoch_table, "--funder", &funder, "--funding", &fund], &early));
    assert!(err.contains("does not move the lease") && err.contains("1545400"), "{err}");
    let d = h.build(&funder, &["committee-roll", "--committee", &committee, "--steps", "505"]);
    let epoch_table2 = h.obj(&d, "epoch table", 1_548_000);
    let t = signed_prices(&h, &market, &members, 1_548_000, "10");
    h.build(&funder, &with(&["c-keep-alive", "--pair", &pair, "--epoch-table", &epoch_table2], &t));
    assert!(h.last.contains("lease until DAA 7596000 (was 6081400)"), "{}", h.last);
    // Nobody renews: settled at the entry.
    h.build(&funder, &["c-lapse-settle", "--pair", &pair]);
    assert!(h.last.contains("out 0: long 10 KAS"), "{}", h.last);

    // Assign: the long signs its side over to the funder at 10.4 and is paid 14 KAS in the same transaction.
    h.build(&funder, &["c-assign", "--pair", &pair, "--side", "long", "--x", "10.4", "--key", &long]);
    assert!(h.last.contains("out 0: leaver 14 KAS"), "{}", h.last);
    assert!(h.fail(&["c-assign", "--pair", &pair, "--side", "long", "--x", "10.4", "--key", &short, "--funder", &funder, "--funding", &fund]).contains("needs a signature"));
    assert!(h.fail(&["c-assign", "--pair", &pair, "--side", "long", "--x", "10.4", "--nb", "9.5", "--key", &long, "--funder", &funder, "--funding", &fund]).contains("entrant's bound"));

    // List, transfer to a signing taker, take by an order, mutual close.
    assert!(h.fail(&["c-transfer", "--pair", &pair, "--side", "long", "--x", "10.4", "--funder", &funder, "--funding", &fund]).contains("not listed"));
    let listed = h.step(&long, &["c-amend", "--pair", &pair, "--side", "long", "--price", "9.9"], "committee pair", 33_500);
    h.build(&funder, &["c-transfer", "--pair", &listed, "--side", "long", "--x", "10"]);
    let order = h.step(&funder, &["c-order", "--market", &market, "--side", "long", "--size", "10", "--limit", "10", "--rate", "1", "--expiry", "9000000"], "committee order", 33_450);
    h.build(&funder, &["c-take", "--pair", &listed, "--order", &order, "--x", "10"]);
    assert!(h.last.contains("the order's part"), "{}", h.last);
    let both = h.step(&short, &["c-amend", "--pair", &listed, "--side", "short", "--price", "10.2"], "committee pair", 33_600);
    h.build(&funder, &["c-mutual-close", "--pair", &both, "--x", "10.1"]);
    let _ = h.step(&long, &["c-add-margin", "--pair", &pair, "--side", "long", "--delta", "0.5"], "committee pair", 33_500);
    assert!(h.last.contains("pair [8.5 .. 12] KAS"), "{}", h.last);
    // Both owners sign any split.
    let out_dir = h.p("coop");
    let out = h.ok(&["c-coop-close", "--pair", &pair, "--long-pay", "12", "--key", &long, "--key", &short, "--out-dir", &out_dir]);
    assert!(out.contains("not submitted"), "{out}");
    // Orders: cancel by the owner, refund by anyone after the expiry.
    let out = h.ok(&["c-cancel", "--order", &order, "--key", &funder, "--out-dir", &out_dir]);
    assert!(out.contains("c-cancel"), "{out}");
    h.build(&funder, &["c-refund", "--order", &order]);
    assert!(h.last.contains("out 0: owner 11.1 KAS"), "{}", h.last);
    // An expired order can still be filled: the watcher says so.
    let (ok, out, err) = h.run(&["c-watch", "--object", &order, "--daa", "9000000"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("has expired and can still be filled"), "{out}\n{err}");

    // A member that signs two prices for one time is slashed by anyone holding both signed signed prices.
    let (pa, pb) = (h.p("two-a.json"), h.p("two-b.json"));
    h.ok(&["price-sign", "--market", &market, "--t0", "33900", "--price", "10", "--key", &members[1], "--out", &pa]);
    h.ok(&["price-sign", "--market", &market, "--t0", "33900", "--price", "10.2", "--key", &members[1], "--out", &pb, "--second-price"]);
    assert!(h.fail(&["price-sign", "--market", &market, "--t0", "33900", "--price", "10.3", "--key", &members[1], "--out", &h.p("two-c.json")]).contains("this key already signed"));
    h.build(&funder, &["member-forfeit", "--committee", &committee, "--signed-price", &pa, "--signed-price", &pb]);
    assert!(h.last.contains("member 1 signed 10 and 10.2 KAS for the time 33900: its 22 KAS are forfeited") && h.last.contains("burned 19.8 KAS"), "{}", h.last);
    let fund9 = h.funding(1_000);
    assert!(h.fail(&["member-forfeit", "--committee", &committee, "--signed-price", &pa, "--signed-price", &pa, "--funder", &funder, "--funding", &fund9]).contains("not a proof"));
    // The committee's exits: member 2 leaves, its stake is released after the epoch and the exit time, an epoch table retires.
    let d = h.build(&funder, &["committee-leave", "--committee", &committee, "--member", "2", "--key", &members[2]]);
    assert!(h.last.contains("its 15 KAS are released at DAA 108000"), "{}", h.last);
    let exit = h.obj(&d, "exit", 33_200);
    h.build(&funder, &["exit-withdraw", "--exit", &exit]);
    assert!(h.last.contains("out 0: the member's stake 15 KAS"), "{}", h.last);
    // The same proof reaches a stake on its way out.
    let (xa, xb) = (h.p("x-a.json"), h.p("x-b.json"));
    h.ok(&["price-sign", "--market", &market, "--t0", "33900", "--price", "10", "--key", &members[2], "--out", &xa]);
    h.ok(&["price-sign", "--market", &market, "--t0", "33900", "--price", "9", "--key", &members[2], "--out", &xb, "--second-price"]);
    h.build(&funder, &["exit-forfeit", "--exit", &exit, "--signed-price", &xa, "--signed-price", &xb]);
    assert!(h.last.contains("its 15 KAS are forfeited") && h.last.contains("burned 13.5 KAS"), "{}", h.last);
    assert!(h.fail(&["committee-leave", "--committee", &committee, "--member", "2", "--key", &members[0], "--funder", &funder, "--funding", &fund]).contains("needs a signature"));
    h.build(&funder, &["epoch-table-retire", "--epoch-table", &epoch_table]);
    let genesis = h.p("committee.json");
    h.build(&funder, &["committee-topup", "--committee", &committee, "--genesis", &genesis, "--member", "0", "--amount", "5"]);
}

/// Stage 2 (docs/DESIGN-COMMITTEE.md 5a): a member signs a false price; it is charged with the signed signed price, the judge's
/// stake refutes the signed price, and the member is slashed. A charge nobody contests lapses and its bond is burned.
#[test]
fn a_false_price_is_charged_judged_and_slashed_from_the_command_line() {
    let mut h = H::new("charge");
    let funder = h.key("funder");
    let judge = h.key("judge");
    let members: Vec<String> = (0..3).map(|i| h.key(&format!("member{i}"))).collect();
    let committee_file = h.p("committee.json");
    // A committee whose charges cost 5 KAS and wait 300 DAA, judged by stakes of 20 KAS aged 200 DAA in rounds of 100.
    let d = h.build(&funder, &["committee-create", "--daa", "30000", "--out", &committee_file, "--charge-bond", "5", "--charge-daa", "300", "--judge-age-daa", "200", "--judge-unbond-daa", "200", "--judge-round-daa", "100", "--judge-min-stake", "20"]);
    let mut committee = h.obj(&d, "committee", 30_000);
    for (i, kas) in [(0, "30"), (1, "22"), (2, "15")] {
        committee = h.step(&funder, &["committee-join", "--committee", &committee, "--genesis", &committee_file, "--member", &i.to_string(), "--amount", kas, "--owner", &members[i]], "committee", 30_100 + i as u64);
    }
    // A judge block no stake could serve is refused when the committee is made.
    let fund = h.funding(1_000);
    assert!(h.fail(&["committee-create", "--daa", "30000", "--judge-round-daa", "0", "--out", &h.p("bad.json"), "--funder", &funder, "--funding", &fund]).contains("the judge block fails the judge's bounds"));
    let feed = h.p("feed.txt");
    std::fs::write(&feed, FEED).unwrap();
    let market = h.p("market.json");
    h.ok(&["c-market", "--committee", &committee_file, "--feed", &feed, "--out", &market]);
    // The judge's stake, bonded before the charge by more than the judge's age.
    let stake = h.step(&funder, &["judge-stake", "--committee", &committee_file, "--value", "20", "--owner", &judge], "judge stake", 30_000);
    assert!(h.last.contains("it judges charges accepted 200 DAA"), "{}", h.last);

    // Member 1 signs 20 for the time 30,500 (the feed was 10): one signed signed price is the whole charge.
    let signed_price = h.p("false.json");
    h.ok(&["price-sign", "--market", &market, "--t0", "30500", "--price", "20", "--key", &members[1], "--out", &signed_price]);
    let d = h.build(&funder, &["charge", "--committee", &committee, "--signed-price", &signed_price]);
    assert!(h.last.contains("signed 20 KAS for the time 30500") && h.last.contains("charge id") && h.last.contains("the bond 5 KAS"), "{}", h.last);
    let (held, charge) = (h.obj(&d, "committee", 30_600), h.obj(&d, "charge", 30_600));
    let out = h.ok(&["c-watch", "--object", &charge, "--daa", "30700"]);
    assert!(out.contains("pending") && out.contains("it waits for a contest until DAA 30900"), "{out}");
    // Pending, it cannot be settled; the signed price of a key that holds no member charges nobody.
    let fund = h.funding(1_000);
    assert!(h.fail(&["charge-settle", "--charge", &charge, "--committee", &held, "--daa", "30700", "--funder", &funder, "--funding", &fund]).contains("can still be contested until DAA 30900"));
    let stray = h.p("stray.json");
    h.ok(&["price-sign", "--market", &market, "--t0", "30500", "--price", "20", "--key", &judge, "--out", &stray]);
    assert!(h.fail(&["charge", "--committee", &committee, "--signed-price", &stray, "--funder", &funder, "--funding", &fund]).contains("no member of the committee holds that key"));

    // The contest (20 KAS on NO), the verdict after the round, the slash.
    let d = h.build(&funder, &["charge-contest", "--charge", &charge, "--stake", &stake, "--key", &judge, "--daa", "30640"]);
    assert!(h.last.contains("contested: 20 KAS on NO"), "{}", h.last);
    let (contested, dispute) = (h.obj(&d, "charge", 30_650), h.obj(&d, "out2-judge-stake", 30_650));
    let out = h.ok(&["c-watch", "--object", &contested, "--daa", "30700"]);
    assert!(out.contains("with the judge"), "{out}");
    let d = h.build(&funder, &["charge-decide", "--charge", &contested, "--dispute", &dispute]);
    assert!(h.last.contains("the signed price is refuted"), "{}", h.last);
    let decided = h.obj(&d, "charge", 30_760);
    let (ok, out, err) = h.run(&["c-watch", "--object", &decided, "--daa", "30800"]);
    assert!(!ok && out.contains("ACT: slash the stake (`charge-settle`)") && err.contains("ACT NOW"), "{out}{err}");
    h.build(&funder, &["charge-settle", "--charge", &decided, "--committee", &held, "--daa", "30800"]);
    // A verdict takes no more than its NO side had at risk (review C5): 20 of the member's 22 KAS.
    assert!(h.last.contains("slashed: 20 KAS of the stake of 22 KAS") && h.last.contains("2 KAS and the bond to the charge's author, 18 KAS burned"), "{}", h.last);
    assert!(h.last.contains("burned 18 KAS") && h.last.contains("7 KAS"), "{}", h.last);

    // Two charges on member 0 for two signed prices nobody contests: each is shown among the member's holds with the other, and
    // 300 DAA after it landed its bond is burned.
    let (ta, tb) = (h.p("ta.json"), h.p("tb.json"));
    h.ok(&["price-sign", "--market", &market, "--t0", "30500", "--price", "10", "--key", &members[0], "--out", &ta]);
    h.ok(&["price-sign", "--market", &market, "--t0", "30501", "--price", "10", "--key", &members[0], "--out", &tb]);
    let d = h.build(&funder, &["charge", "--committee", &committee, "--signed-price", &ta]);
    let id_a = h.last.lines().find(|l| l.starts_with("charge id")).unwrap().split_whitespace().last().unwrap().to_string();
    let (r1, ca) = (h.obj(&d, "committee", 30_600), h.obj(&d, "charge", 30_600));
    let d = h.build(&funder, &["charge", "--committee", &r1, "--signed-price", &tb]);
    let id_b = h.last.lines().find(|l| l.starts_with("charge id")).unwrap().split_whitespace().last().unwrap().to_string();
    let (r2, _cb) = (h.obj(&d, "committee", 30_610), h.obj(&d, "charge", 30_610));
    let fund = h.funding(1_000);
    let err = h.fail(&["charge-settle", "--charge", &ca, "--committee", &r2, "--daa", "30900", "--funder", &funder, "--funding", &fund]);
    assert!(err.contains("not among the stake's holds with this witness") && err.contains("hold-witness"), "{err}");
    let wit = h.ok(&["hold-witness", "--ids", &format!("{id_a},{id_b}"), "--of", &id_a]);
    assert!(wit.contains(&format!("--before {} --later {id_b}", "0".repeat(64))), "{wit}");
    h.build(&funder, &["charge-settle", "--charge", &ca, "--committee", &r2, "--later", &id_b, "--daa", "30900"]);
    assert!(h.last.contains("cleared: the charge lapsed: the hold ends and the bond 5 KAS is burned"), "{}", h.last);

    // Review C5 (C5-F1): a contest nobody answers is a verdict, so a member charged for a TRUE signed price must see it and
    // answer. Member 2 holds judge stake of its own, aged like the judge's.
    let own = h.step(&funder, &["judge-stake", "--committee", &committee_file, "--value", "25", "--owner", &members[2]], "judge stake", 30_000);
    let tc = h.p("true.json");
    h.ok(&["price-sign", "--market", &market, "--t0", "30502", "--price", "10", "--key", &members[2], "--out", &tc]);
    let d = h.build(&funder, &["charge", "--committee", &committee, "--signed-price", &tc]);
    assert!(h.last.contains("The judge's question: is the signed price TRUE?"), "{}", h.last);
    let (rh, cc) = (h.obj(&d, "committee", 30_600), h.obj(&d, "charge", 30_600));
    let (ok, out, err) = h.run(&["c-watch", "--object", &rh, "--me", &members[2], "--daa", "30700"]);
    assert!(!ok && out.contains("member  2 is HELD for a charge") && out.contains("ACT: your member is charged") && err.contains("ACT NOW"), "{out}{err}");
    let (ok, out, _) = h.run(&["c-watch", "--object", &cc, "--me", &members[2], "--daa", "30700"]);
    assert!(!ok && out.contains("ACT: this charge is against your key"), "{out}");
    let d = h.build(&funder, &["charge-contest", "--charge", &cc, "--stake", &stake, "--key", &judge, "--daa", "30640"]);
    let (contested, dispute) = (h.obj(&d, "charge", 30_650), h.obj(&d, "out2-judge-stake", 30_650));
    // The answer names the stake that holds the charge: a dispute on anything else is refused.
    let fund = h.funding(1_000);
    let err = h.fail(&["charge-answer", "--dispute", &dispute, "--charge", &contested, "--side", "yes", "--stake", &own, "--key", &members[2], "--committee", &committee, "--funder", &funder, "--funding", &fund]);
    assert!(err.contains("REFUSED") && err.contains("not a charge the committee wrote against that stake"), "{err}");
    let d = h.build(&funder, &["charge-answer", "--dispute", &dispute, "--charge", &contested, "--side", "yes", "--stake", &own, "--key", &members[2], "--committee", &rh]);
    assert!(h.last.contains("after the answer: YES leads, YES 25 KAS, NO 20 KAS") && h.last.contains("is the signed price TRUE?"), "{}", h.last);
    let answered = h.obj(&d, "out0-judge-stake", 30_700);
    let d = h.build(&funder, &["charge-decide", "--charge", &contested, "--dispute", &answered]);
    assert!(h.last.contains("the signed price is upheld"), "{}", h.last);
    let upheld = h.obj(&d, "charge", 30_810);
    h.build(&funder, &["charge-settle", "--charge", &upheld, "--committee", &rh, "--daa", "30900"]);
    assert!(h.last.contains("cleared: the signed price was upheld: the hold ends and the bond 5 KAS goes to the charged key"), "{}", h.last);

    // Review C5 (C5-F5): a committee whose charges can never be contested says so wherever it is described.
    let weak = h.p("weak.json");
    h.build(&funder, &["committee-create", "--daa", "30000", "--charge-daa", "1", "--out", &weak]);
    assert!(h.last.contains("WARNING: chargeDaa is 1"), "{}", h.last);
    assert!(h.ok(&["committee-check", "--committee", &weak]).contains("no member is ever slashed for a false price"));
    assert!(h.ok(&["committee-check", "--committee", &committee_file]).contains("WARNING: chargeDaa is 300"), "this test's own committee, made for a trial");
    let plain = h.p("plain.json");
    h.build(&funder, &["committee-create", "--daa", "30000", "--out", &plain]);
    assert!(!h.last.contains("WARNING") && !h.ok(&["committee-check", "--committee", &plain]).contains("WARNING"));
}

/// Members that never talk sign the same signed prices: each runs `member-run` on the grid, and their files attest a price.
#[test]
fn unattended_members_sign_the_ticks_of_a_grid() {
    let mut h = H::new("run");
    let (_funder, members, _committee, epoch_table, market) = setup(&mut h);
    let dir = h.p("signed prices");
    let feed = h.p("price.txt");
    std::fs::write(&feed, "10.5
").unwrap();
    // The present is DAA 33,520: the signed price signed is the last whole hundred at least 20 DAA old, 33,500. Three rounds
    // without a clock sign 33,500, 33,600 and 33,700.
    for k in &members {
        let out = h.ok(&["member-run", "--market", &market, "--key", k, "--dir", &dir, "--price-file", &feed, "--daa", "33520", "--count", "3"]);
        assert!(out.contains("signed: 10.5 KAS at DAA 33500") && out.contains("at DAA 33700") && out.contains("3 signed price(s) signed, 0 not signed"), "{out}");
    }
    let mut files: Vec<String> = std::fs::read_dir(&dir).unwrap().map(|e| e.unwrap().path().display().to_string()).filter(|p| p.contains("price-33500-")).collect();
    files.sort();
    assert_eq!(files.len(), 3);
    let args: Vec<String> = files.iter().flat_map(|f| ["--signed-price".to_string(), f.clone()]).collect();
    let out = h.ok(&with(&["price-check", "--market", &market, "--epoch-table", &epoch_table], &args));
    assert!(out.contains("attested: 10.5 KAS at DAA 33500: 3 members signed"), "{out}");
    // The feed moved and the member is started again for the same time: its journal refuses the second price, and with
    // nothing signed the command fails. A feed that cannot be read signs nothing either.
    std::fs::write(&feed, "10.6").unwrap();
    let (ok, out, err) = h.run(&["member-run", "--market", &market, "--key", &members[0], "--dir", &dir, "--price-file", &feed, "--daa", "33520", "--once"]);
    assert!(!ok && out.contains("NOT SIGNED for DAA 33500") && out.contains("this key already signed 10.5 KAS") && err.contains("no signed price was signed"), "{out}{err}");
    let (ok, out, _) = h.run(&["member-run", "--market", &market, "--key", &members[0], "--dir", &dir, "--price-file", &h.p("missing.txt"), "--daa", "34020", "--once"]);
    assert!(!ok && out.contains("NOT SIGNED for DAA 34000"), "{out}");
    // A price command: the first word it prints.
    let out = h.ok(&["member-run", "--market", &market, "--key", &members[0], "--dir", &dir, "--price-cmd", "echo 10.7 KAS", "--daa", "34120", "--once"]);
    assert!(out.contains("signed: 10.7 KAS at DAA 34100"), "{out}");
    // Old signed prices of the key leave the directory.
    let out = h.ok(&["member-run", "--market", &market, "--key", &members[0], "--dir", &dir, "--price", "10.7", "--daa", "34220", "--once", "--keep", "2"]);
    assert!(out.contains("at DAA 34200"), "{out}");
    let left = std::fs::read_dir(&dir).unwrap().map(|e| e.unwrap().file_name().to_string_lossy().into_owned()).filter(|n| n.starts_with("price-33500-")).count();
    assert_eq!(left, 2, "member 0's signed price of 33,500 is pruned; the other members' are theirs");
}

#[test]
fn margin_moves_between_positions_from_the_command_line() {
    let mut h = H::new("cross");
    let (funder, members, _committee, epoch_table, market) = setup(&mut h);
    let (me, other) = (h.key("me"), h.key("other"));
    // Two positions of one key in pairs [9 .. 12] of 10 units: a long, and a short against the same party.
    let a = open_pair(&mut h, &funder, &market, &me, &other);
    let b = open_pair(&mut h, &funder, &market, &other, &me);

    // At 11.3 the long is worth 23 KAS, 16.81325 of it above its maintenance; the short is worth 7 (0.75675 above its
    // maintenance) and 1.64 % from its liquidation (12 / (1.05 x 0.995) = 11.486). The account says what moves that
    // line 10 % away, and where the margin is.
    let (ok, out, err) = h.run(&["c-account", "--me", &me, "--object", &a, "--object", &b, "--price", "11.3"]);
    assert!(!ok && err.contains("ACT NOW: 1 position(s) need margin"), "{out}\n{err}");
    assert!(out.contains("2 position(s) worth 30 KAS; 17.57 KAS of it is margin above maintenance"), "{out}");
    assert!(out.contains("ACT: the short of") && out.contains("9.862425 KAS move its bound by 0.9862425"), "{out}");
    assert!(out.contains("--side long --take 9.862425") && out.contains("--side short --delta 0.9862425"), "{out}");
    assert!(h.fail(&["c-account", "--me", &me, "--object", &a]).contains("no price for the market"));

    // The long takes 9.862425 KAS out at the attested 11.3.
    let t1 = signed_prices(&h, &market, &members, 33_500, "11.3");
    let fund = h.funding(1_000);
    let base = ["c-trim", "--pair", &a, "--side", "long", "--epoch-table", &epoch_table, "--key", &me, "--funder", &funder, "--funding", &fund];
    assert!(h.fail(&with(&base, &t1)).contains("give one of --bound"));
    let near = [&base[..], &["--bound", "10.7"]].concat();
    let err = h.fail(&with(&near, &t1));
    assert!(err.contains("the bound asked for is too near") && err.contains("the nearest bound the attested 11.3 KAS allows is 10.681325 KAS, which frees 16.81325 KAS"), "{err}");
    let much = [&base[..], &["--take", "20"]].concat();
    assert!(h.fail(&with(&much, &t1)).contains("too near"));
    let short = ["c-trim", "--pair", &a, "--side", "short", "--max", "--epoch-table", &epoch_table, "--key", &other, "--funder", &funder, "--funding", &fund];
    // At 11.45 the short of that pair has nothing above its maintenance.
    let t0 = signed_prices(&h, &market, &members, 33_450, "11.45");
    assert!(h.fail(&with(&short, &t0)).contains("the short has nothing above its maintenance to take out"));
    let w = h.step(&funder, &with(&["c-trim", "--pair", &a, "--side", "long", "--take", "9.862425", "--epoch-table", &epoch_table, "--key", &me], &t1), "committee pending part", 33_510);
    assert!(h.last.contains("trim: the long's bound moves from 9 to 9.9862425 KAS and 9.862425 KAS are paid to"), "{}", h.last);
    assert!(h.last.contains("after it the long can be liquidated below"), "{}", h.last);
    let out = h.ok(&["inspect", &w]);
    assert!(out.contains("a trim of the long at 11.3 KAS") && out.contains("the long takes out 9.862425 KAS: its bound moves from 9 to 9.9862425 KAS") && !out.contains("may cure"), "{out}");
    let (ok, out, err) = h.run(&["c-watch", "--me", &other, "--object", &w, "--daa", "33520"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("it can be finalized now") && !out.contains("being liquidated"), "{out}\n{err}");
    assert!(h.fail(&["c-cure", "--pending", &w, "--funder", &me, "--funding", &fund]).contains("no cure"));
    // Finalized at once: the margin is paid and the pair goes on with the new bound.
    let d = h.build(&funder, &["c-finalize", "--pending", &w]);
    assert!(h.last.contains("valid (landed 10 DAA after its time): 9.862425 KAS to the long, whose bound is now 9.9862425 KAS") && h.last.contains("trimmed pair"), "{}", h.last);
    let a2 = h.obj(&d, "committee pair", 33_520);
    // Landed 101 DAA after its time it is void, and the pair is restored.
    let late = h.obj(std::path::Path::new(&w).parent().unwrap().to_str().unwrap(), "committee pending part", 33_601);
    h.build(&funder, &["c-finalize", "--pending", &late]);
    assert!(h.last.contains("VOID") && h.last.contains("restored part"), "{}", h.last);
    // As far as the price allows, with a warning.
    h.build(&funder, &with(&["c-trim", "--pair", &a, "--side", "long", "--max", "--epoch-table", &epoch_table, "--key", &me], &t1));
    assert!(h.last.contains("to 10.681325 KAS and 16.81325 KAS are paid") && h.last.contains("WARNING: this is the nearest bound"), "{}", h.last);

    // The same amount moves the short's bound in the other pair, and the account is quiet.
    let b2 = h.step(&me, &["c-add-margin", "--pair", &b, "--side", "short", "--delta", "0.9862425"], "committee pair", 33_520);
    assert!(h.last.contains("pair [9 .. 12.9862425] KAS"), "{}", h.last);
    let out = h.ok(&["c-account", "--me", &me, "--object", &a2, "--object", &b2, "--price", "11.3"]);
    assert!(out.contains("no position is within 3.00 % of its liquidation") && out.contains("2 position(s) worth 30 KAS"), "{out}");
}

#[test]
fn the_positions_of_a_key_are_kept_linked_by_a_runner() {
    let mut h = H::new("crossrun");
    let (funder, members, _committee, epoch_table, market) = setup(&mut h);
    let (me, other) = (h.key("me"), h.key("other"));
    let a = open_pair(&mut h, &funder, &market, &me, &other);
    let b = open_pair(&mut h, &funder, &market, &other, &me);
    // The account's directory: its two positions. The signed prices and the epoch table are where the members and the roller write.
    let acct = h.p("acct");
    std::fs::create_dir_all(&acct).unwrap();
    let copy = |from: &str, name: &str| {
        let to = format!("{acct}/{name}");
        std::fs::copy(from, &to).unwrap();
        to
    };
    copy(&a, "a-pair.json");
    copy(&b, "b-pair.json");
    let epoch_tables = std::path::Path::new(&epoch_table).parent().unwrap().to_str().unwrap().to_string();
    let t1 = signed_prices(&h, &market, &members, 33_500, "11.3");
    let run = |h: &H, kas: u64, daa: &str| {
        let fund = h.p(&format!("wallet-{kas}.json"));
        std::fs::write(&fund, serde_json::to_string(&json!([{ "txid": format!("{:064x}", 0x77a11e7u64 + kas), "index": 0, "amount": kas * 100_000_000, "daa": 0 }])).unwrap()).unwrap();
        h.ok(&["c-margin-run", "--key", &me, "--dir", &acct, "--signed-prices", &h.dir.display().to_string(), "--epoch-tables", &epoch_tables, "--daa", daa, "--once", "--funding", &fund])
    };
    // A wallet that holds the margin: it is added from the wallet.
    let out = run(&h, 100, "33520");
    assert!(out.contains("the short of") && out.contains("is 1.64 % from its liquidation at 11.3 KAS: it needs 9.862425 KAS"), "{out}");
    assert!(out.contains("pair [9 .. 12.9862425] KAS") && out.contains("round 1 at DAA 33520: 1 transaction(s)") && !out.contains("c-trim:"), "{out}");
    // A wallet that does not: the long's free margin is trimmed for it, with 0.2 KAS for the fees of what follows.
    let out = run(&h, 1, "33520");
    assert!(out.contains("not added from the wallet") && out.contains("trim: the long's bound moves from 9 to 10.0062425 KAS and 10.062425 KAS are paid"), "{out}");
    assert!(out.contains("round 1 at DAA 33520: 1 transaction(s)"), "{out}");
    // No signed price near the present: nothing is priced, nothing is done.
    let out = run(&h, 1, "33700");
    assert!(out.contains("not watched this round: no signed price of the market") && out.contains("round 1 at DAA 33700: 0 transaction(s)"), "{out}");
    // A pending trim of the account is finalized, and nothing is trimmed again while it is pending.
    let w = h.step(&funder, &with(&["c-trim", "--pair", &a, "--side", "long", "--take", "9.862425", "--epoch-table", &epoch_table, "--key", &me], &t1), "committee pending part", 33_510);
    copy(&w, "w-pending.json");
    let out = run(&h, 1, "33520");
    assert!(out.contains("valid (landed 10 DAA after its time): 9.862425 KAS to the long") && out.contains("a trim of yours is pending"), "{out}");
    assert!(out.contains("round 1 at DAA 33520: 1 transaction(s)"), "{out}");

    // Review C8 (C8-F1): a pair file that appears while the runner runs is not one of its positions, whatever key it
    // names. Two rounds, ten seconds apart; the file is planted between them.
    let fund = h.p("wallet-100.json");
    let planted = format!("{acct}/planted-pair.json");
    let child = bin()
        .args(["c-margin-run", "--key", &me, "--dir", &acct, "--signed-prices", &h.dir.display().to_string(), "--epoch-tables", &epoch_tables, "--daa", "33520", "--count", "2", "--every-secs", "10", "--funding", &fund])
        .stdout(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    std::thread::sleep(std::time::Duration::from_secs(4));
    std::fs::copy(&b, &planted).unwrap();
    let out = String::from_utf8_lossy(&child.wait_with_output().unwrap().stdout).into_owned();
    assert!(out.contains("planted-pair.json: NOT MANAGED") && out.contains("round 2 at DAA 33520"), "{out}");
    assert!(!out.contains("planted-pair.json --side"), "{out}");
}

#[test]
fn two_positions_become_one_account_from_the_command_line() {
    let mut h = H::new("xacct");
    // The funder of the fixture is the executor here.
    let (exec, members, _committee, epoch_table1, market1) = setup(&mut h);
    let (me, other) = (h.key("me"), h.key("other"));
    // A second market priced by the same committee.
    let feed2 = h.p("feed2.txt");
    std::fs::write(&feed2, FEED.replace("example underlying", "another underlying")).unwrap();
    let market2 = h.p("market2.json");
    h.ok(&["c-market", "--committee", &h.p("committee.json"), "--feed", &feed2, "--out", &market2]);
    // The owner is long 10 units of market 1 and short 10 units of market 2, each in a pair [9 .. 12] opened at 10.
    let a = open_pair(&mut h, &exec, &market1, &me, &other);
    let b = open_pair(&mut h, &exec, &market2, &other, &me);
    // A second epoch table of the epoch (a roll writes four): one a leg.
    let tdir = std::path::Path::new(&epoch_table1).parent().unwrap();
    let mut all: Vec<PathBuf> = std::fs::read_dir(tdir).unwrap().map(|e| e.unwrap().path()).filter(|p| p.to_string_lossy().ends_with("-epoch-table.json")).collect();
    all.sort();
    let epoch_table2 = all.iter().map(|p| p.display().to_string()).find(|p| *p != epoch_table1).expect("a second epoch table");
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&epoch_table2).unwrap()).unwrap();
    v["daa"] = json!(33_000);
    std::fs::write(&epoch_table2, serde_json::to_string_pretty(&v).unwrap()).unwrap();
    // The members sign both markets for one time.
    let sign = |h: &H, t0: u64, p1: &str, p2: &str| -> Vec<String> {
        let mut v = vec!["--epoch-table1".to_string(), epoch_table1.clone(), "--epoch-table2".to_string(), epoch_table2.clone()];
        for (n, (market, price)) in [(&market1, p1), (&market2, p2)].iter().enumerate() {
            for (i, k) in members.iter().enumerate() {
                let f = h.p(&format!("m{}-price-{t0}-{i}.json", n + 1));
                h.ok(&["price-sign", "--market", market, "--t0", &t0.to_string(), "--price", price, "--key", k, "--out", &f]);
                v.push(format!("--signed-price{}", n + 1));
                v.push(f);
            }
        }
        v
    };

    // The swap at the agreed prices 11 and 10.5: the long is worth 10 x (11 - 9) = 20 KAS, the short 10 x (12 - 10.5)
    // = 15 KAS; the executor takes both pairs over (posting its own bounds) and funds the account.
    let x = h.step(&exec, &["x-swap", "--pair1", &a, "--side1", "long", "--x1", "11", "--pair2", &b, "--side2", "short", "--x2", "10.5", "--b-margin", "20", "--key", &me, "--daa", "33500"], "cross account", 33_500);
    assert!(h.last.contains("the owner gives up position(s) worth 35 KAS at the agreed prices and is owed 35 KAS in the account"), "{}", h.last);
    assert!(h.last.contains("the counterparty holds: pair [8.55 .. 12] KAS") && h.last.contains("the counterparty holds: pair [9 .. 12.6] KAS"), "{}", h.last);
    assert!(h.last.contains("leg 1: long 10 units") && h.last.contains("leg 2: short 10 units") && h.last.contains("margin: a 35 KAS, b 20 KAS (the pot 55 KAS)"), "{}", h.last);
    let fund = h.funding(1_000);
    assert!(h.fail(&["x-swap", "--pair1", &a, "--side1", "short", "--x1", "11", "--b-margin", "20", "--key", &me, "--daa", "33500", "--funder", &exec, "--funding", &fund]).contains("needs a signature"));

    // One position: market 2 at 13 alone costs the short leg 25 KAS and the owner is liquidated; with market 1 at
    // 13.5 the long leg has gained 25 KAS and nobody is.
    let out = h.ok(&["x-show", "--account", &x, "--price1", "11", "--price2", "13"]);
    assert!(out.contains("a is owed 10 KAS") && out.contains("the OWNER (a) can be LIQUIDATED"), "{out}");
    let out = h.ok(&["x-show", "--account", &x, "--price1", "13.5", "--price2", "13"]);
    assert!(out.contains("a is owed 35 KAS (leg 1 25 KAS, leg 2 -25 KAS)") && out.contains("neither party can be liquidated"), "{out}");
    assert!(out.contains("a close by the owner (a) pays it 33.675 KAS"), "{out}");
    assert!(h.fail(&["x-show", "--account", &x, "--price1", "11"]).contains("two legs"));
    let out = h.ok(&["c-watch", "--me", &me, "--object", &x, "--daa", "33700"]);
    assert!(out.contains("leg 1: long 10 units") && out.contains("lease ends in"), "{out}");

    // The liquidation at (11, 13), for one time of both markets.
    let t1 = sign(&h, 33_600, "11", "13");
    let w = h.step(&exec, &with(&["x-liquidate", "--account", &x, "--side", "a"], &t1), "cross pending claim", 33_610);
    assert!(h.last.contains("liquidation of the owner (a): the fee 1.2 KAS") && h.last.contains("by adding 3.205 KAS"), "{}", h.last);
    assert!(h.fail(&with(&["x-liquidate", "--account", &x, "--side", "b", "--funder", &exec, "--funding", &fund], &t1)).contains("do not liquidate that side"));
    let out = h.ok(&["inspect", &w]);
    assert!(out.contains("a liquidation of the owner (a) for the time 33600") && out.contains("VALID") && !out.contains("WARNING"), "{out}");
    let (ok, out, err) = h.run(&["c-watch", "--me", &me, "--object", &w, "--daa", "33620"]);
    assert!(!ok && err.contains("ACT NOW") && out.contains("your side of the account is being liquidated"), "{out}\n{err}");
    h.build(&me, &["x-cure", "--pending", &w]);
    assert!(h.last.contains("cured: 3.205 KAS added; the margins are now a 38.205 KAS, b 20 KAS") && h.last.contains("cured account"), "{}", h.last);
    h.build(&exec, &["x-finalize", "--pending", &w]);
    assert!(h.last.contains("valid: 54 KAS to the winner") && h.last.contains("the proposer's fee 1.2 KAS"), "{}", h.last);
    let late = h.obj(std::path::Path::new(&w).parent().unwrap().to_str().unwrap(), "cross pending claim", 33_701);
    h.build(&exec, &["x-finalize", "--pending", &late]);
    assert!(h.last.contains("VOID") && h.last.contains("restored account"), "{}", h.last);
    assert!(h.fail(&["x-cure", "--pending", &late, "--funder", &me, "--funding", &fund]).contains("this claim is void"));

    // A leg priced for another signed price is refused before anything is built.
    let mut mixed = sign(&h, 33_650, "11", "13");
    let other_price = sign(&h, 33_640, "11", "13");
    for i in 0..mixed.len() {
        if mixed[i] == "--signed-price2" {
            mixed[i + 1] = other_price[i + 1].clone();
        }
    }
    assert!(h.fail(&with(&["x-liquidate", "--account", &x, "--side", "a", "--funder", &exec, "--funding", &fund], &mixed)).contains("an account is priced for one time"));

    // The owner closes at (13.5, 13): paid its side at the prices moved by the tolerance against it.
    let t2 = sign(&h, 33_700, "13.5", "13");
    let w = h.step(&exec, &with(&["x-close", "--account", &x, "--side", "a", "--key", &me], &t2), "cross pending claim", 33_710);
    assert!(h.last.contains("close: the owner (a) is paid 33.675 KAS"), "{}", h.last);
    h.build(&exec, &["x-finalize", "--pending", &w]);
    assert!(h.last.contains("valid (landed 10 DAA after its time): the owner 33.675 KAS, the counterparty 21.525 KAS"), "{}", h.last);

    // Margin, the lease, the lapse, and the close by both.
    h.build(&me, &["x-add-margin", "--account", &x, "--side", "a", "--amount", "5"]);
    assert!(h.last.contains("margin: a 40 KAS, b 20 KAS"), "{}", h.last);
    assert!(h.fail(&with(&["x-keep-alive", "--account", &x, "--leg", "2", "--funder", &exec, "--funding", &fund], &t2)).contains("does not move the lease"));
    h.build(&exec, &["x-lapse-settle", "--account", &x]);
    assert!(h.last.contains("the owner 35 KAS") && h.last.contains("the counterparty 20.2 KAS"), "{}", h.last);
    let out_dir = h.p("coop");
    let out = h.ok(&["x-coop-close", "--account", &x, "--a-pay", "30", "--key", &me, "--key", &exec, "--out-dir", &out_dir]);
    assert!(out.contains("the owner 30 KAS") && out.contains("the counterparty (the rest, less the fee)"), "{out}");
    // The swap signed on two machines. The owner builds it with the executor's UTXOs (its address and a funding file
    // it gave) and signs the pairs; the executor's funding input is left open.
    let exec_addr = h.ok(&["address", "--key", &exec]).split_whitespace().find(|w| w.contains(':')).expect("an address").to_string();
    let offer = h.funding(1_000);
    let req = h.p("request.json");
    let swap = ["x-swap", "--pair1", &a, "--side1", "long", "--x1", "11", "--pair2", &b, "--side2", "short", "--x2", "10.5", "--b-margin", "20", "--daa", "33500", "--funder", &exec_addr, "--funding", &offer, "--partial", &req];
    let out = h.ok(&[&swap[..], &["--key", &me]].concat());
    assert!(out.contains("(partly signed)") && out.contains("LEFT TO SIGN") && out.contains("written:") && !out.contains("SUBMITTED"), "{out}");
    // A signature a pair's script checks is not left to a co-signer.
    assert!(h.fail(&swap).contains("inside its script"));
    assert!(h.fail(&[&swap[..], &["--key", &me, "--submit"]].concat()).contains("not submitted here"));
    // The executor reads what the transaction does (from the transaction, not from the file's labels), signs its
    // input and would send it; the objects' files are written on its machine too.
    let dir = h.p("cosigned");
    let out = h.ok(&["cosign", "--tx", &req, "--key", &exec, "--out-dir", &dir]);
    assert!(out.contains("YOU SIGN THIS") && out.contains("signed by the other party") && out.contains("to you ("), "{out}");
    assert!(out.contains("cross account") && out.contains("margin: a 35 KAS, b 20 KAS") && out.contains("committee pair"), "{out}");
    assert!(out.contains("you put in 1000 KAS: ") && out.contains("KAS go into objects in which you have a part, 0 KAS into objects in which you have none, 0 KAS to other addresses or unknown scripts") && out.contains("yours in it: ") && out.contains("your part of it at its entries: 20 KAS of the 55.2 KAS it holds") && out.contains("not submitted") && !out.contains("WARNING"), "{out}");
    // The budget assumed for the open input is what a key input costs.
    assert!(out.contains("in  2: yours (100001 units)"), "{out}");
    let x2 = h.obj(&format!("{dir}/dry-run"), "cross account", 33_500);
    assert!(h.ok(&["x-show", "--account", &x2, "--price1", "11", "--price2", "10.5"]).contains("a is owed 35 KAS"));
    // Another key signs nothing; a file changed after the owner signed fails the owner's signatures.
    assert!(h.fail(&["cosign", "--tx", &req, "--key", &other]).contains("needs a signature of"));
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&req).unwrap()).unwrap();
    let outs = v["partial"]["tx"]["outputs"].as_array().expect("outputs").len();
    let val = v["partial"]["tx"]["outputs"][outs - 1]["value"].as_u64().expect("a value");
    v["partial"]["tx"]["outputs"][outs - 1]["value"] = json!(val + 100_000_000);
    v["partial"]["tx"]["outputs"][2]["value"] = json!(v["partial"]["tx"]["outputs"][2]["value"].as_u64().unwrap() - 100_000_000);
    let bad = h.p("tampered.json");
    std::fs::write(&bad, serde_json::to_string(&v).unwrap()).unwrap();
    let (ok, out, err) = h.run(&["cosign", "--tx", &bad, "--key", &exec, "--out-dir", &dir]);
    // The writer's signatures are checked before anything is printed or signed.
    assert!(!ok && err.contains("REFUSED") && err.contains("which the other party should have signed, fails its script") && !out.contains("YOU SIGN THIS"), "{out}\n{err}");
}

/// The thin family from the command line (docs/DESIGN-COMMITTEE.md 8a): a library, an account between a user and an
/// executor in a committee market, and the life of its claims with a second executor that watches. A false claim is
/// seen by `pos-show`, disputed and ended; a true one is settled; a late one is ended; the two parties close together.
#[test]
fn an_position_of_the_thin_family_and_its_claims_from_the_command_line() {
    let mut h = H::new("thin");
    let (exec, members, _committee, epoch_table, market) = setup(&mut h);
    let (me, exec2) = (h.key("me"), h.key("exec2"));
    // A library of one copy of each script.
    let ld = h.build(&exec, &["lib-create", "--copies", "1"]);
    let lib = h.last.lines().find_map(|l| l.strip_prefix("library ")).and_then(|l| l.split(':').next()).expect("the library's id").to_string();
    assert_eq!(lib.len(), 64, "{lib}");
    let script = |h: &H, dir: &str, name: &str| h.obj(dir, &format!("script-{name}"), 33_050);
    let (s_add, s_decl, s_settle, s_late, s_disp, s_both) =
        (script(&h, &ld, "KpfTAdd"), script(&h, &ld, "KpfTClose"), script(&h, &ld, "KpfTSettle"), script(&h, &ld, "KpfTLate"), script(&h, &ld, "KpfTDispute"), script(&h, &ld, "KpfTBoth"));
    // The user is long 10 units at 10 against the executor, 40 and 60 KAS of margin; claims wait 50 DAA.
    // A position is opened in a library whose genesis the tool read: a bare id is refused unless the user says it
    // checked the library itself (review T1b, F4).
    let genesis = std::fs::read_dir(&ld).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("the genesis transaction's file").display().to_string();
    assert!(h.ok(&["lib-check", "--lib", &genesis]).contains(&format!("library {lib}: its genesis writes the family's scripts and nothing else")));
    // The library's registry: anchors under one id. An order or a position enters through one, with its owner's signature
    // (a position: both parties'), and every order and position of these tests is under that id.
    let bd = h.build(&exec, &["registry-create", "--lib", &genesis, "--copies", "2"]);
    assert!(h.last.contains("2 anchors of the library"), "{}", h.last);
    let registry = std::fs::read_dir(&bd).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("the registry's genesis").display().to_string();
    let (anchor, s_place, s_open) = (h.obj(&bd, "anchor", 33_060), script(&h, &ld, "KpfTPlace"), script(&h, &ld, "KpfTOpen"));
    assert!(h.ok(&["lib-check", "--lib", &genesis, "--registry", &registry]).contains("its genesis writes anchors of this library and nothing else"));
    assert!(h.fail(&["lib-check", "--lib", &genesis, "--registry", &genesis]).contains("not an anchor"), "a library's genesis is not a registry's");
    assert!(h.ok(&["pos-show", "--object", &anchor]).contains("anchor of a registry"));
    let f0 = h.funding(1_000);
    let bare = ["pos-open", "--lib", &lib, "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", &exec, "--market1", &market, "--size1", "10", "--dir1", "long", "--x1", "10", "--a", &me, "--b", &exec, "--a-margin", "40", "--b-margin", "60", "--daa", "33100", "--funder", &me, "--funding", &f0];
    assert!(h.fail(&bare).contains("REFUSED: --lib is a bare id"));
    let mut unchecked = bare.to_vec();
    unchecked.push("--lib-unchecked");
    assert!(h.ok(&unchecked).contains("WARNING: the library's genesis was NOT checked"));
    let position = h.step(
        &me,
        &["pos-open", "--lib", &genesis, "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", &exec, "--market1", &market, "--size1", "10", "--dir1", "long", "--x1", "10", "--a", &me, "--b", &exec, "--a-margin", "40", "--b-margin", "60", "--dispute-daa", "50", "--daa", "33100"],
        "position",
        33_100,
    );
    assert!(h.last.contains("the state is published in the transaction"), "{}", h.last);
    let shown = h.ok(&["pos-show", "--object", &position]);
    assert!(shown.contains("position of library") && shown.contains("a dispute period of 50 DAA"), "{shown}");
    // The user adds 5 KAS; the copy of the script it used is the next one's.
    let d = h.build(&me, &["pos-add-margin", "--position", &position, "--script", &s_add, "--side", "a", "--amount", "5"]);
    assert!(h.last.contains("margin: a 45"), "{}", h.last);
    let position = h.obj(&d, "position", 33_200);
    let s_add = h.obj(&d, "script-KpfTAdd", 33_200);
    // A false claim: the user states 60 KAS at a price where the rule gives it less.
    let claim = h.step(&me, &["pos-close", "--position", &position, "--script", &s_decl, "--side", "a", "--t0", "33300", "--p1", "10", "--amount", "60"], "claim", 33_310);
    assert!(h.last.contains("CHECK: FALSE"), "{}", h.last);
    let s_decl2 = h.obj(&h.last_dir(), "script-KpfTClose", 33_310);
    // The second executor reads the claim, sees it false, disputes it, and ends it after the dispute period.
    let seen = h.ok(&["pos-show", "--object", &claim]);
    assert!(seen.contains("CHECK: FALSE") && seen.contains("in time"), "{seen}");
    let d = h.build(&exec2, &["pos-dispute", "--claim", &claim, "--script", &s_disp]);
    assert!(!h.last.contains("WARNING"), "{}", h.last);
    let (dis, s_disp) = (h.obj(&d, "disputed claim", 33_320), h.obj(&d, "script-KpfTDispute", 33_320));
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-settle", "--claim", &dis, "--script", &s_settle, "--funder", &exec2, "--funding", &f]).contains("disputed"));
    let d = h.build(&exec2, &["pos-lapse", "--claim", &dis, "--script", &s_disp]);
    assert!(h.last.contains("the position again"), "{}", h.last);
    let position = h.obj(&d, "position", 33_400);
    // A true claim: the tool states what the rule gives. A dispute of it is warned against; it is settled.
    let d = h.build(&me, &["pos-close", "--position", &position, "--script", &s_decl2, "--side", "a", "--t0", "33450", "--p1", "10"]);
    assert!(h.last.contains("CHECK: the amount is what the rule gives"), "{}", h.last);
    let (claim, s_decl3) = (h.obj(&d, "claim", 33_460), h.obj(&d, "script-KpfTClose", 33_460));
    h.build(&exec2, &["pos-dispute", "--claim", &claim, "--script", &h.obj(&d_of(&s_disp), "script-KpfTDispute", 33_400)]);
    assert!(h.last.contains("WARNING"), "{}", h.last);
    h.build(&exec2, &["pos-settle", "--claim", &claim, "--script", &s_settle]);
    assert!(h.last.contains("pays a"), "{}", h.last);
    // A claim that landed late is neither settled nor disputed, only ended.
    let late = h.step(&me, &["pos-close", "--position", &position, "--script", &s_decl3, "--side", "a", "--t0", "33450", "--p1", "10"], "claim", 90_000_000);
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-settle", "--claim", &late, "--script", &s_settle, "--funder", &exec2, "--funding", &f]).contains("late"));
    h.build(&exec2, &["pos-late", "--claim", &late, "--script", &s_late]);
    // The two parties close together; one alone cannot.
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-close", "--mutual", "--position", &position, "--script", &s_both, "--to-a", "45", "--funder", &me, "--funding", &f]).contains("signature"));
    h.build(&me, &["pos-close", "--mutual", "--position", &position, "--script", &s_both, "--to-a", "45", "--key", &exec]);
    assert!(h.last.contains("pays a 45"), "{}", h.last);
    // A liquidation the rule does not give (at the entry price): seen false, disputed by the counterparty, and either
    // cured under the dispute or ended after the dispute period.
    let (s_liq, s_lset, s_cure, s_ldis) = (script(&h, &ld, "KpfTLiq"), script(&h, &ld, "KpfTLiqSettle"), script(&h, &ld, "KpfTCure"), script(&h, &ld, "KpfTLiqDispute"));
    let d = h.build(&exec2, &["pos-liquidate", "--position", &position, "--script", &s_liq, "--side", "a", "--t0", "33500", "--p1", "10", "--fee", "1", "--add", "5"]);
    assert!(h.last.contains("CHECK: FALSE. The rule does not liquidate"), "{}", h.last);
    let (lq, s_liq2) = (h.obj(&d, "liquidation", 33_510), h.obj(&d, "script-KpfTLiq", 33_510));
    let d = h.build(&exec, &["pos-dispute", "--claim", &lq, "--script", &s_ldis]);
    assert!(!h.last.contains("WARNING"), "{}", h.last);
    let (dl, s_ldis2) = (h.obj(&d, "disputed liquidation", 33_520), h.obj(&d, "script-KpfTLiqDispute", 33_520));
    // A disputed liquidation is not cured: its liquidator proves it, or it lapses.
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-cure", "--claim", &dl, "--script", &s_cure, "--funder", &me, "--funding", &f]).contains("disputed"));
    h.build(&exec, &["pos-lapse", "--claim", &dl, "--script", &s_ldis2]);
    assert!(h.last.contains("the position again"), "{}", h.last);
    // The rule's liquidation: at 5.5 the long side is below its maintenance. The tool refuses to state one at 10.
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-liquidate", "--position", &position, "--script", &s_liq2, "--side", "a", "--t0", "33600", "--p1", "10", "--funder", &exec2, "--funding", &f]).contains("does not liquidate"));
    let d = h.build(&exec2, &["pos-liquidate", "--position", &position, "--script", &s_liq2, "--side", "a", "--t0", "33600", "--p1", "5.5"]);
    assert!(h.last.contains("CHECK: the liquidation is within the rule at these prices"), "{}", h.last);
    let lq = h.obj(&d, "liquidation", 33_610);
    // The side cures it with its own key, and nobody else can; not cured, it is settled after the dispute period.
    h.build(&me, &["pos-cure", "--claim", &lq, "--script", &s_cure]);
    assert!(h.last.contains("cured with"), "{}", h.last);
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-cure", "--claim", &lq, "--script", &s_cure, "--funder", &exec2, "--funding", &f]).contains("signature"));
    h.build(&exec2, &["pos-settle", "--claim", &lq, "--script", &s_lset]);
    assert!(h.last.contains("pays the liquidator"), "{}", h.last);
    let seen = h.ok(&["pos-show", "--object", &lq]);
    assert!(seen.contains("liquidation of side a") && seen.contains("in time"), "{seen}");
    // The proof. The three members sign 11 for the time 33,700; the user declares at the committee's signed price (the tool takes
    // the signed price and the price from the signed files), is disputed, and answers with the same files.
    let signed_prices: Vec<String> = members
        .iter()
        .enumerate()
        .map(|(i, k)| {
            let f = h.p(&format!("thin-price-{i}.json"));
            h.ok(&["price-sign", "--market", &market, "--t0", "33700", "--price", "11", "--key", k, "--out", &f]);
            f
        })
        .collect();
    let signed_by = ["--epoch-table1", &epoch_table, "--signed-price1", &signed_prices[0], "--signed-price1", &signed_prices[1], "--signed-price1", &signed_prices[2]];
    let mut args = vec!["pos-close", "--position", &position, "--script", &s_decl3, "--side", "a"];
    args.extend(signed_by);
    let d = h.build(&me, &args);
    assert!(h.last.contains("attested (leg 1): 11 KAS at DAA 33700") && !h.last.contains("WARNING") && h.last.contains("CHECK: the amount is what the rule gives"), "{}", h.last);
    let claim = h.obj(&d, "claim", 33_710);
    let d = h.build(&exec2, &["pos-dispute", "--claim", &claim, "--script", &h.obj(&d_of(&s_disp), "script-KpfTDispute", 33_400)]);
    assert!(h.last.contains("WARNING"), "{}", h.last);
    let dis = h.obj(&d, "disputed claim", 33_720);
    let s_prove = script(&h, &ld, "KpfTProve");
    let mut args = vec!["pos-prove", "--claim", &dis, "--script", &s_prove];
    args.extend(signed_by);
    h.build(&me, &args);
    assert!(h.last.contains("proved: pays a"), "{}", h.last);
    // A claim typed in at a price of the claimer's own says so; one that states more than the committee's price gives
    // is not proved with the members' signed prices, and is refuted with them by anyone: the position again.
    let d = h.build(&me, &["pos-close", "--position", &position, "--script", &s_decl3, "--side", "a", "--t0", "33700", "--p1", "11", "--amount", "70"]);
    assert!(h.last.contains("stated at prices of the funder's own") && h.last.contains("CHECK: FALSE. The rule gives"), "{}", h.last);
    let claim = h.obj(&d, "claim", 33_710);
    let d = h.build(&exec2, &["pos-dispute", "--claim", &claim, "--script", &h.obj(&d_of(&s_disp), "script-KpfTDispute", 33_400)]);
    let dis = h.obj(&d, "disputed claim", 33_720);
    let f = h.funding(1_000);
    let mut args = vec!["pos-prove", "--claim", &dis, "--script", &s_prove, "--funder", &me, "--funding", &f];
    args.extend(signed_by);
    assert!(h.fail(&args).contains("nobody proves it"));
    let mut args = vec!["pos-refute", "--claim", &dis, "--script", &s_prove];
    args.extend(signed_by);
    let d = h.build(&exec, &args);
    assert!(h.last.contains("refuted: the position again") && h.last.contains("half of the bond of who claimed"), "{}", h.last);
    assert_eq!(std::fs::read_to_string(h.obj(&d, "position", 33_730)).unwrap().contains("\"redeem\""), true);
    // The claim the committee's price bears is not refuted with them.
    let d = h.build(&me, &["pos-close", "--position", &position, "--script", &s_decl3, "--side", "a", "--t0", "33700", "--p1", "11"]);
    let claim = h.obj(&d, "claim", 33_710);
    let d = h.build(&exec2, &["pos-dispute", "--claim", &claim, "--script", &h.obj(&d_of(&s_disp), "script-KpfTDispute", 33_400)]);
    let dis = h.obj(&d, "disputed claim", 33_720);
    let f = h.funding(1_000);
    let mut args = vec!["pos-refute", "--claim", &dis, "--script", &s_prove, "--funder", &exec, "--funding", &f];
    args.extend(signed_by);
    assert!(h.fail(&args).contains("it is not refuted"));
    // The way out of a committee that stopped: the user says no price was signed since 33,600. Nobody showing one, it
    // is settled at the entries after the exit time; the second executor, with the members' signed price of 33,700, ends it.
    let (s_exit, s_qend, s_qref) = (script(&h, &ld, "KpfTExit"), script(&h, &ld, "KpfTExitEnd"), script(&h, &ld, "KpfTExitRefute"));
    let d = h.build(&me, &["pos-exit", "--position", &position, "--script", &s_exit, "--side", "a", "--since", "33600"]);
    assert!(h.last.contains("no price of one of the position's markets since DAA 33600"), "{}", h.last);
    let q = h.obj(&d, "exit claim", 33_650);
    h.build(&exec2, &["pos-settle", "--claim", &q, "--script", &s_qend]);
    assert!(h.last.contains("settled at the entries: pays a"), "{}", h.last);
    let mut args = vec!["pos-refute", "--claim", &q, "--script", &s_qref];
    args.extend(signed_by);
    h.build(&exec2, &args);
    assert!(h.last.contains("ended: the committee signed after DAA 33600"), "{}", h.last);
    // A claim since after the members' signed price is not answered by it; one that names a time to come is ended by anyone.
    let d = h.build(&me, &["pos-exit", "--position", &position, "--script", &s_exit, "--side", "a", "--since", "33800"]);
    let q2 = h.obj(&d, "exit claim", 33_850);
    let f = h.funding(1_000);
    let mut args = vec!["pos-refute", "--claim", &q2, "--script", &s_qref, "--funder", &exec2, "--funding", &f];
    args.extend(signed_by);
    assert!(h.fail(&args).contains("older than the claim"));
    let q3 = h.obj(&d, "exit claim", 33_750);
    h.build(&exec2, &["pos-late", "--claim", &q3, "--script", &s_exit]);
    // Orders between two users. A buy of 3 and a sell of 10 that takes at least 2 a match: the second executor matches
    // 3 at the seller's price; the buy is used up, 7 of the sell rest, and the position is the two users'.
    let (s_match, s_cancel) = (script(&h, &ld, "KpfTMatch"), script(&h, &ld, "KpfTCancel"));
    let common = ["--lib", &genesis, "--anchor", &anchor, "--script", &s_place, "--registry", &registry, "--market1", &market, "--expiry", "40000", "--dispute-daa", "50"];
    let place = |h: &mut H, who: &str, extra: &[&str], daa: u64| -> String {
        let mut a = vec!["order-place"];
        a.extend(common);
        a.extend(extra);
        h.step(who, &a, "order", daa)
    };
    let buy = place(&mut h, &me, &["--side", "long", "--size", "3", "--limit", "10.1", "--margin", "12", "--tip", "0.3"], 33_900);
    let sell = place(&mut h, &exec, &["--side", "short", "--size", "10", "--limit", "10", "--margin", "40", "--tip", "1", "--min-fill", "2"], 33_900);
    assert!(h.ok(&["pos-show", "--object", &sell]).contains("a match takes at least"), "an order is shown");
    let d = h.build(&exec2, &["order-match", "--long", &buy, "--short", &sell, "--script", &s_match, "--size", "3", "--price", "10"]);
    assert!(h.last.contains("the long order: used up") && h.last.contains("units rest") && h.last.contains("the tips 0.6 KAS (the sender's"), "{}", h.last);
    let (matched, rest, s_match2) = (h.obj(&d, "position", 33_950), h.obj(&d, "order", 33_950), h.obj(&d, "script-KpfTMatch", 33_950));
    let shown = h.ok(&["pos-show", "--object", &matched]);
    assert!(shown.contains("position of library") && shown.contains("holds 24 KAS"), "{shown}");
    // The position of a match is a position: its owner adds margin.
    h.build(&me, &["pos-add-margin", "--position", &matched, "--script", &s_add, "--side", "a", "--amount", "1"]);
    // A second fill between the same two users, and the two positions merged into one by the second executor.
    let again = place(&mut h, &me, &["--side", "long", "--size", "2", "--limit", "10.1", "--margin", "8", "--tip", "0.2"], 33_955);
    let d2 = h.build(&exec2, &["order-match", "--long", &again, "--short", &rest, "--script", &s_match2, "--size", "2", "--price", "10"]);
    let second = h.obj(&d2, "position", 33_958);
    let s_merge = script(&h, &ld, "KpfTMerge");
    // (Nobody signs a merge: the two positions are of one registry.)
    h.build(&exec2, &["pos-merge", "--position", &matched, "--with", &second, "--script", &s_merge]);
    assert!(h.last.contains("merged: one position of the two; the sender keeps 0.01 KAS"), "{}", h.last);
    // The position the two opened directly at the start is of the same two users, market and terms: it merges with
    // the position of the match as well (13 units). A position does not merge with itself.
    h.build(&exec2, &["pos-merge", "--position", &matched, "--with", &position, "--script", &s_merge]);
    assert!(h.last.contains("long 13 units") && h.last.contains("merged: one position of the two"), "{}", h.last);
    let f1 = h.funding(1_000);
    assert!(h.fail(&["pos-merge", "--position", &matched, "--with", &matched, "--script", &s_merge, "--funder", &exec2, "--funding", &f1]).contains("not merged with itself"));
    // A user leaves two positions that cancel each other: `me` is long 3 against the first executor from 10 and the
    // second executor is long 3 against `me` from 10.2. The files in either order; nobody signs: the two positions are of one registry.
    let open3 = |h: &mut H, who: &str, a: &str, b: &str, x1: &str, min_counter: &str| -> String {
        let mut args = vec!["pos-open", "--lib", &genesis, "--market1", &market, "--size1", "3", "--dir1", "long", "--x1", x1, "--a", a, "--b", b, "--a-margin", "12", "--b-margin", "12", "--dispute-daa", "50", "--daa", "33960", "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", b];
        if !min_counter.is_empty() {
            args.extend(["--a-min-counter-margin", min_counter, "--b-min-counter-margin", min_counter]);
        }
        h.step(who, &args, "position", 33_960)
    };
    // Each party asks 6 KAS of whoever faces it. (By default each asks what the other posts, 12: then the one that
    // stays short, 0.6 KAS down, is short of what the one that comes in asked, and the user does not leave this way.)
    let (nx, ny) = (open3(&mut h, &me, &me, &exec, "10", "6"), open3(&mut h, &exec2, &exec2, &me, "10.2", "6"));
    let (dx, dy) = (open3(&mut h, &me, &me, &exec, "10", ""), open3(&mut h, &exec2, &exec2, &me, "10.2", ""));
    let fd = h.funding(1_000);
    assert!(h.fail(&["pos-novate", "--position", &dy, "--with", &dx, "--script", &script(&h, &ld, "KpfTNovate"), "--funder", &exec, "--funding", &fd]).contains("asked"), "the default asks");
    let s_nov = script(&h, &ld, "KpfTNovate");
    h.build(&exec, &["pos-novate", "--position", &ny, "--with", &nx, "--script", &s_nov]);
    assert!(h.last.contains("the user that leaves is paid 24.585 KAS (0.6 KAS of it from") && h.last.contains("long 3 units") && h.last.contains("from 10.2 KAS") && h.last.contains("margin: a 12 KAS, b 11.4 KAS"), "{}", h.last);
    let f2 = h.funding(1_000);
    assert!(h.fail(&["pos-novate", "--position", &nx, "--with", &position, "--script", &s_nov, "--funder", &exec, "--funding", &f2]).contains("does not leave"));
    // Two markets into one position. A second market of the same committee; `me` is long 3 in the first against the first
    // executor (the position `dx` above, from 10) and the executor is long 2 in the second against `me`: the two join
    // them (both sign), and `me` has one position, long 3 in the first market and short 2 in the second, one pot of margin.
    let feed2 = h.p("feed2.txt");
    std::fs::write(&feed2, FEED.replace("example underlying", "another underlying")).unwrap();
    let market2 = h.p("market2.json");
    h.ok(&["c-market", "--committee", &h.p("committee.json"), "--feed", &feed2, "--out", &market2]);
    let other = h.step(&exec, &["pos-open", "--lib", &genesis, "--market1", &market2, "--size1", "2", "--dir1", "long", "--x1", "20", "--a", &exec, "--b", &me, "--a-margin", "9", "--b-margin", "7", "--dispute-daa", "50", "--daa", "33960", "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", &me], "position", 33_960);
    let s_join = script(&h, &ld, "KpfTJoin");
    let fk = h.funding(1_000);
    assert!(h.fail(&["pos-join", "--position", &dx, "--with", &other, "--script", &s_join, "--funder", &exec2, "--funding", &fk]).contains("key"), "a join the two users do not sign");
    let dj = h.build(&exec2, &["pos-join", "--position", &dx, "--with", &other, "--script", &s_join, "--key", &me, "--key", &exec]);
    assert!(h.last.contains("joined: one position of two legs") && h.last.contains("leg 1: long 3 units") && h.last.contains("leg 2: short 2 units") && h.last.contains("margin: a 18.995 KAS, b 20.995 KAS"), "{}", h.last);
    let fj = h.funding(1_000);
    assert!(h.fail(&["pos-join", "--position", &dx, "--with", &dy, "--script", &s_join, "--funder", &exec2, "--funding", &fj]).contains("not joined"));
    // One side of the cross position. Written with its legs the other way round and back; a fill of the same two users
    // folded into its first leg (4 units); its first leg sold to the second executor (the position `ny` above: the
    // second executor long 3 against `me` from 10.2), sent by a third key and signed by the position's two users: `me` is paid its
    // margin in that position, and its margin in the cross position stays, with the 0.6 KAS it made, behind the leg it
    // keeps.
    let cross = h.obj(&dj, "position", 34_000);
    let (s_turn, s_fold, s_leave) = (script(&h, &ld, "KpfTTurn"), script(&h, &ld, "KpfTFold"), script(&h, &ld, "KpfTLeave"));
    h.build(&exec2, &["pos-turn", "--position", &cross, "--script", &s_turn, "--mode", "legs"]);
    assert!(h.last.contains("leg 1: short 2 units") && h.last.contains("leg 2: long 3 units") && h.last.contains("turned: the same position, its legs"), "{}", h.last);
    h.build(&exec2, &["pos-turn", "--position", &cross, "--script", &s_turn, "--mode", "users"]);
    assert!(h.last.contains("leg 1: short 3 units") && h.last.contains("margin: a 20.995 KAS, b 18.995 KAS"), "{}", h.last);
    let one_more = open3(&mut h, &me, &me, &exec, "10.4", "");
    h.build(&exec2, &["pos-fold", "--position", &cross, "--with", &one_more, "--script", &s_fold]);
    assert!(h.last.contains("leg 1: long 6 units") && h.last.contains("leg 2: short 2 units") && h.last.contains("folded:"), "{}", h.last);
    let fn_ = h.funding(1_000);
    assert!(h.fail(&["pos-leave", "--position", &cross, "--with", &ny, "--script", &s_leave, "--funder", &exec2, "--funding", &fn_]).contains("key"), "a leg leaves a position by its two users' signatures");
    h.build(&exec2, &["pos-leave", "--position", &cross, "--with", &ny, "--script", &s_leave, "--key", &me, "--key", &exec]);
    assert!(h.last.contains("the leg leaves the position: 300000000 units; the user that sold is paid 11.985 KAS") && h.last.contains("0.6 KAS to its margin there"), "{}", h.last);
    assert!(h.last.contains("leg 1: short 2 units") && h.last.contains("margin: a 19.595 KAS"), "{}", h.last);
    let fl = h.funding(1_000);
    assert!(h.fail(&["pos-leave", "--position", &dx, "--with", &ny, "--script", &s_leave, "--funder", &exec2, "--funding", &fl]).contains("one leg"));
    // The least fill and the template are held: a buy of 1 against the rest (7, least 2) is refused, and so is an order
    // of another dispute period.
    let one = place(&mut h, &me, &["--side", "long", "--size", "1", "--limit", "10.1", "--margin", "4", "--tip", "0.1"], 33_960);
    let f = h.funding(1_000);
    assert!(h.fail(&["order-match", "--long", &one, "--short", &rest, "--script", &s_match2, "--size", "1", "--price", "10", "--funder", &exec2, "--funding", &f]).contains("at least"));
    let mut a = vec!["order-place", "--lib", &genesis, "--anchor", &anchor, "--script", &s_place, "--registry", &registry, "--market1", &market, "--expiry", "40000", "--dispute-daa", "60", "--side", "long", "--size", "3", "--limit", "10.1", "--margin", "12"];
    a.extend(["--tip", "0.3"]);
    let other = h.step(&me, &a, "order", 33_960);
    assert!(h.fail(&["order-match", "--long", &other, "--short", &rest, "--script", &s_match2, "--size", "3", "--price", "10", "--funder", &exec2, "--funding", &f]).contains("not of one template"));
    // A price above the buyer's limit (10.1) is refused, for a size the sell would take.
    let three = place(&mut h, &me, &["--side", "long", "--size", "3", "--limit", "10.1", "--margin", "12", "--tip", "0.3"], 33_960);
    assert!(h.fail(&["order-match", "--long", &three, "--short", &rest, "--script", &s_match2, "--size", "3", "--price", "10.2", "--funder", &exec2, "--funding", &f]).contains("the price is not above the long's limit"));
    // What rests is its owner's to take back, and anybody's to return from its expiry on.
    h.build(&exec, &["order-cancel", "--order", &rest, "--script", &s_cancel]);
    assert!(h.last.contains("28.7 KAS back to"), "{}", h.last);
    assert!(h.fail(&["order-cancel", "--order", &rest, "--script", &s_cancel, "--funder", &exec2, "--funding", &f]).contains("signature"));
    h.build(&exec2, &["order-expire", "--order", &rest, "--script", &s_cancel]);
    assert!(h.last.contains("usable from DAA 40000") || h.last.contains("lock time"), "{}", h.last);
    // A file whose state is not the one its script carries, and a script that is not the command's, are refused.
    let mut v: Value = serde_json::from_str(&std::fs::read_to_string(&position).unwrap()).unwrap();
    let t = v["thin"].as_str().unwrap().to_string();
    let other = h.ok(&["pos-show", "--object", &late]);
    assert!(other.contains("LATE"), "{other}");
    // The state of another object in the position's file: read, and refused because the script carries another hash.
    let lv: Value = serde_json::from_str(&std::fs::read_to_string(&late).unwrap()).unwrap();
    v["thin"] = lv["thin"].clone();
    let forged = h.p("forged.json");
    std::fs::write(&forged, serde_json::to_string(&v).unwrap()).unwrap();
    assert!(h.fail(&["pos-show", "--object", &forged]).contains("not the one its script carries"));
    // Bytes that are no state at all.
    v["thin"] = json!(format!("{}ff", &t[..t.len() - 2]));
    std::fs::write(&forged, serde_json::to_string(&v).unwrap()).unwrap();
    h.fail(&["pos-show", "--object", &forged]);
    let f = h.funding(1_000);
    assert!(h.fail(&["pos-add-margin", "--position", &position, "--script", &s_both, "--side", "a", "--amount", "1", "--funder", &me, "--funding", &f]).contains("not a copy of KpfTAdd"));
    let _ = s_add;
}

/// The directory of a file.
fn d_of(file: &str) -> String {
    PathBuf::from(file).parent().unwrap().display().to_string()
}

/// The thin family from two machines: each user's key is on its own, and what both sign goes from one to the other as
/// a file (`--partial`, `cosign`). A position is opened (the counterparty's margin from its own coin) and closed by
/// both, an executor paying for the close: three machines sign that one in turn.
#[test]
fn the_thin_family_from_two_machines() {
    let mut h = H::new("thin2");
    let (exec, _members, _committee, _epoch_table, market) = setup(&mut h);
    let (me, you) = (h.key("me"), h.key("you"));
    let addr = |h: &H, k: &str| h.ok(&["address", "--key", k]).split_whitespace().find(|w| w.starts_with("kaspatest:")).expect("an address").to_string();
    let (you_at, exec_at) = (addr(&h, &you), addr(&h, &exec));
    let ld = h.build(&exec, &["lib-create", "--copies", "1"]);
    let tx_of = |d: &str| std::fs::read_dir(d).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("a transaction's file").display().to_string();
    let genesis = tx_of(&ld);
    let bd = h.build(&exec, &["registry-create", "--lib", &genesis, "--copies", "2"]);
    let registry = tx_of(&bd);
    let (anchor, s_open, s_both) = (h.obj(&bd, "anchor", 33_060), h.obj(&ld, "script-KpfTOpen", 33_050), h.obj(&ld, "script-KpfTBoth", 33_050));
    let (out_a, out_b, out_e) = (h.p("machine-a"), h.p("machine-b"), h.p("machine-e"));
    let (fa, fb, fe) = (h.funding(1_000), h.funding(61), h.funding(1_000));
    let (p1, p2, p3) = (h.p("open.partial.json"), h.p("close.partial.json"), h.p("close.partial2.json"));

    // 1. The first machine has its user's key and the counterparty's address and listed coin: alone it does not open.
    let open = ["pos-open", "--lib", &genesis, "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", &me, "--market1", &market, "--size1", "10", "--dir1", "long", "--x1", "10", "--a", &me, "--b", &you_at, "--a-margin", "40", "--b-margin", "60", "--b-funding", &fb, "--dispute-daa", "50", "--daa", "33100", "--funder", &me, "--funding", &fa, "--out-dir", &out_a];
    assert!(h.fail(&open).contains("needs a signature"), "an opening is both parties'");
    let mut partly = open.to_vec();
    partly.extend(["--partial", &p1]);
    let out = h.ok(&partly);
    assert!(out.contains("(partly signed)") && out.contains("WAITS FOR THE SIGNATURE OF") && out.contains("LEFT TO SIGN") && out.contains(&you_at), "{out}");
    let mut sent = partly.clone();
    sent.push("--submit");
    assert!(h.fail(&sent).contains("not submitted here"));
    // What only one signs is not written partly signed.
    let f = h.funding(1_000);
    assert!(h.fail(&["lib-create", "--copies", "1", "--partial", &p2, "--funder", &exec_at, "--funding", &f]).contains("--partial` is for what two users sign"));

    // 2. The second machine reads the file, and signs what it read. It is told what it cannot know without a node.
    let cosign = ["cosign", "--tx", &p1, "--lib", &genesis, "--registry", &registry, "--key", &you, "--out-dir", &out_b];
    assert!(h.fail(&cosign).contains("REFUSED: the inputs must be looked up at the node"));
    let mut offline = cosign.to_vec();
    offline.push("--inputs-unchecked");
    let out = h.ok(&offline);
    assert!(out.contains("YOU SIGN THIS") && out.contains("WARNING: the inputs were NOT looked up") && out.contains("yours in it") && out.contains("not submitted: a dry run"), "{out}");
    assert!(out.contains("its genesis writes anchors of this library and nothing else") && out.contains("in plain coins you put in 61 KAS and are paid 1 KAS"), "{out}");
    // The position's file is the same on both machines.
    let (a_file, b_file) = (h.obj(&format!("{out_a}/dry-run"), "position", 33_100), h.obj(&format!("{out_b}/dry-run"), "position", 33_100));
    let text = |f: &str| serde_json::from_str::<Value>(&std::fs::read_to_string(f).unwrap()).unwrap();
    assert_eq!((&text(&a_file)["thin"], &text(&a_file)["outpoint"]), (&text(&b_file)["thin"], &text(&b_file)["outpoint"]));
    // Refused: a registry it did not check, a library it did not name, a key nothing waits for.
    let without = |drop: &str| -> Vec<&str> {
        let i = offline.iter().position(|x| *x == drop).unwrap();
        offline.iter().enumerate().filter(|(j, _)| *j != i && *j != i + 1).map(|(_, x)| *x).collect()
    };
    assert!(h.fail(&without("--registry")).contains("REFUSED: this transaction enters a registry"));
    assert!(h.fail(&without("--lib")).contains("--lib"));
    let mut other = without("--key");
    other.extend(["--key", &exec]);
    assert!(h.fail(&other).contains("nothing in this transaction waits for a key given"));
    // Refused: a file that was changed. An output's value (the first machine's signatures no longer hold); a state
    // left out (an input or output the tool cannot read).
    let v = text(&p1);
    let bad = h.p("bad.partial.json");
    let mut t = v.clone();
    let val = t["partial"]["tx"]["outputs"][0]["value"].as_u64().expect("an output's value");
    t["partial"]["tx"]["outputs"][0]["value"] = json!(val - 1);
    std::fs::write(&bad, serde_json::to_string(&t).unwrap()).unwrap();
    let mut on_bad = offline.clone();
    on_bad[2] = &bad;
    assert!(h.fail(&on_bad).contains("REFUSED"), "a changed output");
    let mut t = v.clone();
    t["states"] = json!([]);
    std::fs::write(&bad, serde_json::to_string(&t).unwrap()).unwrap();
    assert!(h.fail(&on_bad).contains("nor an object whose state the file gives"), "a state left out");

    // 3. The close by both, paid for by an executor. The user writes it with its key and the executor's address and
    // listed coin; the counterparty signs and passes it on; the executor signs its coin last.
    let close = ["pos-close", "--mutual", "--position", &b_file, "--script", &s_both, "--to-a", "45", "--key", &me, "--funder", &exec_at, "--funding", &fe, "--out-dir", &out_a, "--partial", &p2];
    let out = h.ok(&close);
    assert!(out.contains("WAITS FOR THE SIGNATURE OF") && out.contains("LEFT TO SIGN"), "{out}");
    let second = ["cosign", "--tx", &p2, "--lib", &genesis, "--key", &you, "--inputs-unchecked", "--out-dir", &out_b];
    assert!(h.fail(&second).contains("signatures are still missing"), "the executor's coin is still open");
    let mut passed = second.to_vec();
    passed.extend(["--out", &p3]);
    let out = h.ok(&passed);
    assert!(out.contains("still to be signed by") && out.contains(&exec_at) && out.contains("KAS to") && out.contains("(you)"), "{out}");
    // The counterparty's key signs nothing in what it already signed.
    let mut again = passed.clone();
    again[2] = &p3;
    assert!(h.fail(&again).contains("nothing in this transaction waits for a key given"));
    let out = h.ok(&["cosign", "--tx", &p3, "--lib", &genesis, "--key", &exec, "--inputs-unchecked", "--out-dir", &out_e]);
    assert!(out.contains("YOU SIGN THIS") && out.contains("not submitted: a dry run") && out.contains("compute mass") && !out.contains("FAILED"), "{out}");
    // It is the transaction one machine with the three keys makes.
    let one = ["pos-close", "--mutual", "--position", &b_file, "--script", &s_both, "--to-a", "45", "--key", &me, "--key", &you, "--funder", &exec, "--funding", &fe, "--out-dir", &out_e];
    let whole = h.ok(&one);
    let id = |o: &str| o.lines().find(|l| l.starts_with("txid ")).expect("a txid").to_string();
    assert_eq!(id(&out), id(&whole));
}

/// `exec-run` without a node (`--daa`, `--funding`): one round over the folder as it is, nothing sent. Two orders that
/// cross are matched at the limit of the one that stood first; the positions of two fills between the same two users
/// are merged; what would cost the sender is left alone.
#[test]
fn an_executor_runs_rounds_over_its_folder() {
    let mut h = H::new("exec");
    let (exec, _members, _committee, _epoch_table, market) = setup(&mut h);
    let (me, you) = (h.key("me"), h.key("you"));
    let ld = h.build(&exec, &["lib-create", "--copies", "1"]);
    let tx_of = |d: &str| std::fs::read_dir(d).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("a transaction's file").display().to_string();
    let genesis = tx_of(&ld);
    let bd = h.build(&exec, &["registry-create", "--lib", &genesis, "--copies", "2"]);
    let registry = tx_of(&bd);
    let (anchor, s_place) = (h.obj(&bd, "anchor", 33_060), h.obj(&ld, "script-KpfTPlace", 33_050));
    let common = ["--lib", &genesis, "--anchor", &anchor, "--script", &s_place, "--registry", &registry, "--market1", &market, "--expiry", "40000", "--dispute-daa", "50"];
    let place = |h: &mut H, who: &str, extra: &[&str], daa: u64| -> String {
        let mut a = vec!["order-place"];
        a.extend(common);
        a.extend(extra);
        h.step(who, &a, "order", daa)
    };
    let folder = h.p("folder");
    std::fs::create_dir_all(&folder).unwrap();
    let put = |file: &str| {
        let to = std::path::Path::new(&folder).join(std::path::Path::new(file).file_name().unwrap());
        std::fs::copy(file, &to).unwrap();
        to.display().to_string()
    };
    // A buy of 3 that stood first, and a sell of 10 that came to it: matched for 3 at the buy's limit.
    let buy = put(&place(&mut h, &me, &["--side", "long", "--size", "3", "--limit", "10.1", "--margin", "12", "--tip", "0.3"], 33_900));
    let sell = put(&place(&mut h, &you, &["--side", "short", "--size", "10", "--limit", "10", "--margin", "40", "--tip", "1", "--min-fill", "2"], 33_950));
    let f = h.funding(50);
    let run = |h: &H, extra: &[&str], daa: &str| -> String {
        let mut a = vec!["exec-run", "--dir", &folder, "--lib", &genesis, "--registry", &registry, "--funder", &exec, "--funding", &f, "--daa", daa];
        a.extend(extra);
        h.ok(&a)
    };
    let out = run(&h, &[], "34000");
    assert!(out.contains("match 3 units at 10.1") && out.contains("1 sent (a trial: nothing is sent without --submit)"), "{out}");
    assert!(out.contains("2 objects live of 2 in the folder"), "{out}");
    // An order past its expiry less the watchtower is not matched; asked to, the executor returns one past its expiry.
    let out = run(&h, &[], "39950");
    assert!(out.contains("0 sent"), "{out}");
    let out = run(&h, &["--do", "expire"], "40000");
    assert!(out.contains("0 sent"), "at its expiry an order is not yet returned: {out}");
    // One copy of the script and one coin: one transaction a round.
    let out = run(&h, &["--do", "expire"], "40001");
    assert!(out.contains("returned after its expiry") && out.contains("no copy of KpfTCancel is free this round") && out.contains("1 sent"), "{out}");
    assert!(h.fail(&["exec-run", "--dir", &folder, "--lib", &genesis, "--registry", &registry, "--funder", &exec, "--funding", &f, "--daa", "34000", "--do", "everything"]).contains("--do `everything`"));
    // What a match must leave the sender: asked more than its two tips' shares, the match is not built at all;
    // asked a little less than they are, it is built, and left alone for its fee.
    let out = run(&h, &["--min-gain", "5"], "34000");
    assert!(!out.contains("left alone") && out.contains("0 sent"), "{out}");
    let out = run(&h, &["--min-gain", "0.599"], "34000");
    assert!(out.contains("left alone") && out.contains("0 sent"), "{out}");
    // The round's files are those a single command writes: the position, and what rests of the sell.
    let made = format!("{folder}/dry-run");
    let (position, rest) = (h.obj(&made, "position", 34_010), h.obj(&made, "order", 34_010));
    std::fs::remove_file(&buy).unwrap();
    std::fs::remove_file(&sell).unwrap();
    let (position, _rest) = (put(&position), put(&rest));
    for e in std::fs::read_dir(&made).unwrap() {
        std::fs::remove_file(e.unwrap().path()).unwrap();
    }
    // A second buy of the same user: matched against what rests, and the two positions are then one.
    put(&place(&mut h, &me, &["--side", "long", "--size", "2", "--limit", "10.1", "--margin", "8", "--tip", "0.2"], 34_020));
    let out = run(&h, &[], "34100");
    assert!(out.contains("match 2 units at 10 ") && out.contains("1 sent"), "{out}");
    let second = put(&h.obj(&made, "position", 34_110));
    let out = run(&h, &["--do", "merge", "--min-gain", "-1"], "34200");
    assert!(out.contains("merge (") && out.contains("1 sent"), "{out}");
    let _ = (position, second);
    // The chain is read only with a node.
    assert!(h.fail(&["registry-sync", "--dir", &folder, "--lib", &genesis, "--registry", &registry]).contains("give --node URL"));
}


/// A library with a fee pool (`lib-create --committee`): the oracle fees its operations leave are for that committee; without one
/// they stay in the copies, and the tool says so.
#[test]
fn a_library_with_a_fee_pool_from_the_command_line() {
    let mut h = H::new("oracle fees");
    let exec = h.key("exec");
    let committee = "52".repeat(32);
    let genesis_in = |dir: &str| std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("the genesis transaction").display().to_string();
    // (6 KAS a copy: at 5 the genesis of a library of 63 scripts is above a block's storage mass.)
    let ld = h.build(&exec, &["lib-create", "--copies", "1", "--value", "7", "--committee", &committee]);
    assert!(h.last.contains(&format!("oracle fees: every operation leaves 0.002 KAS in the copy of the script it used; they gather in the library's fee pool for the committee {committee}")), "{}", h.last);
    assert!(h.last.contains("A copy keeps 7 KAS"), "{}", h.last);
    let genesis = genesis_in(&ld);
    let out = h.ok(&["lib-check", "--lib", &genesis]);
    assert!(out.contains("its genesis writes the family's scripts and nothing else") && out.contains(&format!("for the committee {committee} (a copy keeps 7 KAS)")), "{out}");
    // Without a committee: a library, and a note.
    let bare = h.build(&exec, &["lib-create", "--copies", "1"]);
    assert!(h.last.contains("NOTE: no --committee: this library has no fee pool"), "{}", h.last);
    assert!(h.ok(&["lib-check", "--lib", &genesis_in(&bare)]).contains("NOTE: this library has no fee pool"));
    // A committee that is no id; a sweep and a payment without a node; a sweep in a library without a fee pool.
    let f = h.funding(100);
    assert!(h.fail(&["lib-create", "--copies", "1", "--committee", "zz", "--funder", &exec, "--funding", &f]).contains("--committee"));
    assert!(h.fail(&["fee-sweep", "--lib", &genesis, "--funder", &exec, "--funding", &f]).contains("read at the node"));
    assert!(h.fail(&["fee-pay", "--lib", &genesis, "--funder", &exec, "--funding", &f]).contains("read at the node"));
    assert!(h.fail(&["fee-sweep", "--lib", &genesis_in(&bare), "--funder", &exec, "--funding", &f]).contains("this library has no fee pool"));
    assert!(h.fail(&["fee-sweep", "--lib", &genesis, "--copy", "KpfTPay", "--funder", &exec, "--funding", &f]).contains("read at the node"));
}

/// The watchtower of `exec-run`: a committee that stops signing while a user is winning does not send the user out at the
/// entries. The user's loop claims its position at the last price a quorum signed, proves the claim if it is
/// disputed, and settles it; and a round says what margin stands under the committee beside the committee's stake.
#[test]
fn a_user_guards_its_position_against_a_committee_that_stops_signing() {
    let mut h = H::new("watch");
    let (exec, members, _committee, epoch_table, market) = setup(&mut h);
    let me = h.key("me");
    let ld = h.build(&exec, &["lib-create", "--copies", "1"]);
    let tx_of = |d: &str| std::fs::read_dir(d).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("a transaction's file").display().to_string();
    let genesis = tx_of(&ld);
    let bd = h.build(&exec, &["registry-create", "--lib", &genesis, "--copies", "2"]);
    let registry = tx_of(&bd);
    let (anchor, s_open, s_decl, s_disp) = (h.obj(&bd, "anchor", 33_060), h.obj(&ld, "script-KpfTOpen", 33_050), h.obj(&ld, "script-KpfTClose", 33_050), h.obj(&ld, "script-KpfTDispute", 33_050));
    // The user is long 10 units at 10 against the executor, 40 and 60 KAS of margin; a claim waits 50 DAA, and lands
    // within 100 DAA of its time (the market's).
    let position = h.step(
        &me,
        &["pos-open", "--lib", &genesis, "--anchor", &anchor, "--script", &s_open, "--registry", &registry, "--key", &exec, "--market1", &market, "--size1", "10", "--dir1", "long", "--x1", "10", "--a", &me, "--b", &exec, "--a-margin", "40", "--b-margin", "60", "--dispute-daa", "50", "--daa", "33100"],
        "position",
        33_100,
    );
    let dir = |h: &H, name: &str| {
        let d = h.p(name);
        std::fs::create_dir_all(&d).unwrap();
        d
    };
    let put = |folder: &str, file: &str| std::fs::copy(file, std::path::Path::new(folder).join(std::path::Path::new(file).file_name().unwrap())).map(|_| ()).unwrap();
    // The members' signed prices as a member's runner names them, in the folder the user's machine receives them in.
    let sign = |h: &H, into: &str, t0: u64, price: &str| -> Vec<String> {
        members
            .iter()
            .enumerate()
            .map(|(i, k)| {
                let f = format!("{into}/price-{t0}-member{i}.json");
                h.ok(&["price-sign", "--market", &market, "--t0", &t0.to_string(), "--price", price, "--key", k, "--out", &f]);
                f
            })
            .collect()
    };
    let (folder, gticks) = (dir(&h, "gfolder"), dir(&h, "gticks"));
    put(&folder, &position);
    sign(&h, &gticks, 33_300, "10.5");
    let last = sign(&h, &gticks, 33_400, "11");
    let f = h.funding(50);
    let run = |h: &H, folder: &str, signed_prices: &str, extra: &[&str], daa: &str| -> String {
        let mut a = vec!["exec-run", "--dir", folder, "--lib", &genesis, "--registry", &registry, "--funder", &me, "--funding", &f, "--daa", daa, "--do", "watch", "--signed-prices", signed_prices, "--epoch-table", &epoch_table];
        a.extend(extra);
        h.ok(&a)
    };
    // The newest signed price is 20 DAA old: the committee is signing, nothing is done. What stands under the committee is said.
    let out = run(&h, &folder, &gticks, &[], "33420");
    assert!(out.contains("0 sent") && !out.contains("watchtower:"), "{out}");
    assert!(out.contains("1 positions, 100 KAS of margin in this folder's sight; the committee's stake is 67 KAS (1.49 of it)"), "{out}");
    // 50 DAA old (a third of the 100 DAA a claim may land in has passed): the position is worth more than the user's
    // margin at 11, and is claimed at that time.
    let out = run(&h, &folder, &gticks, &[], "33450");
    assert!(out.contains("watchtower: no price signed for 50 DAA: position") && out.contains("claimed at the last one (11 KAS at DAA 33400)") && out.contains("1 sent"), "{out}");
    // A signed price of a time to come, signed by a quorum, does not make the committee look as if it were still signing:
    // the newest signed price not after the present is the one that counts.
    let ahead = dir(&h, "gticks-ahead");
    for t in &last {
        put(&ahead, t);
    }
    sign(&h, &ahead, 35_000, "11");
    let out = run(&h, &folder, &ahead, &[], "33450");
    assert!(out.contains("claimed at the last one (11 KAS at DAA 33400)") && out.contains("1 sent"), "{out}");
    // Told to wait longer, it waits; told of a gain it does not have, it leaves the position alone.
    assert!(run(&h, &folder, &gticks, &["--silence", "60"], "33450").contains("0 sent"));
    assert!(run(&h, &folder, &gticks, &["--watch-gain", "50"], "33450").contains("0 sent"));
    // 90 DAA old: a claim sent now would not land in time, and the tool says what is left.
    let out = run(&h, &folder, &gticks, &[], "33490");
    assert!(out.contains("it cannot be claimed at that price any more") && out.contains("0 sent"), "{out}");
    // The last price is against the user (9): silence costs it nothing, and nothing is claimed.
    let (folder2, down) = (dir(&h, "gfolder2"), dir(&h, "gticks-down"));
    put(&folder2, &position);
    sign(&h, &down, 33_410, "9");
    let out = run(&h, &folder2, &down, &[], "33460");
    assert!(out.contains("0 sent") && !out.contains("claimed"), "{out}");
    // No signed price of a quorum in the folder (the two smaller members of three: 37 of 67 KAS is below 67 %).
    let (folder3, two) = (dir(&h, "gfolder3"), dir(&h, "gticks-two"));
    put(&folder3, &position);
    for t in &last[1..] {
        put(&two, t);
    }
    assert!(run(&h, &folder3, &two, &[], "33450").contains("no price a quorum signed in the last 100 DAA (the time a claim may land in) is in the signed prices' folder, of 1 signed prices of that time there. Nothing to claim by"));
    // The claim as the tool declares it by hand at that time, disputed by the counterparty: the watchtower proves it with
    // the same signatures. And the claim undisputed, a dispute period old: the watchtower settles it.
    let mut args = vec!["pos-close", "--position", &position, "--script", &s_decl, "--side", "a", "--epoch-table1", &epoch_table];
    for t in &last {
        args.extend(["--signed-price1", t.as_str()]);
    }
    let d = h.build(&me, &args);
    let claim = h.obj(&d, "claim", 33_410);
    let d = h.build(&exec, &["pos-dispute", "--claim", &claim, "--script", &s_disp]);
    let dis = h.obj(&d, "disputed claim", 33_420);
    let folder4 = dir(&h, "gfolder4");
    put(&folder4, &dis);
    let out = run(&h, &folder4, &gticks, &[], "33440");
    assert!(out.contains("watchtower: disputed claim") && out.contains("proved with the committee's signatures") && out.contains("1 sent"), "{out}");
    // What the watchtower read it keeps under names of its own (a later file of the same name does not take a price
    // away): with the signed prices' folder emptied of that time, the same machine still proves.
    assert!(std::fs::read_dir(std::path::Path::new(&folder4).join("prices-kept")).unwrap().count() >= 3);
    assert!(run(&h, &folder4, &down, &[], "33440").contains("proved with the committee's signatures"));
    // A machine that never had the signed prices of the time does not prove, and the tool says the claim lapses.
    let folder6 = dir(&h, "gfolder6");
    put(&folder6, &dis);
    assert!(run(&h, &folder6, &down, &[], "33440").contains("it cannot be proved from here, and lapses"));
    let folder5 = dir(&h, "gfolder5");
    put(&folder5, &claim);
    assert!(run(&h, &folder5, &gticks, &[], "33440").contains("0 sent"), "before its dispute period");
    let out = run(&h, &folder5, &gticks, &[], "33470");
    assert!(out.contains("watchtower: claim") && out.contains("settled") && out.contains("1 sent"), "{out}");
    // The watchtower without the committee's prices; a limit without the committee's stake.
    let base = ["exec-run", "--dir", &folder, "--lib", &genesis, "--registry", &registry, "--funder", &me, "--funding", &f, "--daa", "33450"];
    let mut a = base.to_vec();
    a.extend(["--do", "watch"]);
    assert!(h.fail(&a).contains("the watchtower reads the committee's signed prices"));
    let mut a = base.to_vec();
    a.extend(["--max-exposure", "0.5"]);
    assert!(h.fail(&a).contains("measured against the committee's stake"));
}

/// `--max-exposure`: an executor does not match what would put more margin under a committee than the share of the
/// committee's stake it allows itself (the stake is the sum of the members' weights in an epoch table it was given).
#[test]
fn an_executor_leaves_unmatched_what_would_stand_above_its_limit() {
    let mut h = H::new("exposure");
    let (exec, _members, _committee, epoch_table, market) = setup(&mut h);
    let (me, you) = (h.key("me"), h.key("you"));
    let ld = h.build(&exec, &["lib-create", "--copies", "1"]);
    let tx_of = |d: &str| std::fs::read_dir(d).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with("-tx.json")).expect("a transaction's file").display().to_string();
    let genesis = tx_of(&ld);
    let bd = h.build(&exec, &["registry-create", "--lib", &genesis, "--copies", "2"]);
    let registry = tx_of(&bd);
    let (anchor, s_place) = (h.obj(&bd, "anchor", 33_060), h.obj(&ld, "script-KpfTPlace", 33_050));
    let common = ["--lib", &genesis, "--anchor", &anchor, "--script", &s_place, "--registry", &registry, "--market1", &market, "--expiry", "40000", "--dispute-daa", "50"];
    let folder = h.p("folder");
    std::fs::create_dir_all(&folder).unwrap();
    // A buy of 3 with 12 KAS of margin and a sell of 10 with 40 KAS (the orders of the executor's own test).
    let orders: [(&String, &[&str], u64); 2] = [
        (&me, &["--side", "long", "--size", "3", "--limit", "10.1", "--margin", "12", "--tip", "0.3"], 33_900),
        (&you, &["--side", "short", "--size", "10", "--limit", "10", "--margin", "40", "--tip", "1", "--min-fill", "2"], 33_950),
    ];
    for (who, extra, daa) in orders {
        let mut a = vec!["order-place"];
        a.extend(common);
        a.extend(extra);
        let file = h.step(who, &a, "order", daa);
        std::fs::copy(&file, std::path::Path::new(&folder).join(std::path::Path::new(&file).file_name().unwrap())).unwrap();
    }
    let f = h.funding(50);
    let run = |h: &H, max: &str| h.ok(&["exec-run", "--dir", &folder, "--lib", &genesis, "--registry", &registry, "--funder", &exec, "--funding", &f, "--daa", "34000", "--epoch-table", &epoch_table, "--max-exposure", max]);
    // The two margins are 52 KAS and the committee's stake 67 KAS: half of the stake is 33.5 KAS, the whole of it 67.
    let out = run(&h, "0.5");
    assert!(out.contains("cross and are left unmatched: their margins would stand above --max-exposure of the committee's stake") && out.contains("0 sent"), "{out}");
    let out = run(&h, "1");
    assert!(out.contains("match 3 units at 10.1") && out.contains("1 sent"), "{out}");
}
